import { Agent, GameEngine } from "../game";
import { AnimState } from "../../types";

export class AnimationSystem {
    public update(dt: number, engine: GameEngine) {
        for (const agent of engine.agents) {
            // 1. Update Visual Timers
            if (agent.hitFlashTimer > 0) {
                agent.hitFlashTimer -= dt;
            }

            // 2. Derive Animation State (Priority Based)
            // Priority: DEAD > STUN > HIT > ATTACK > MOVE > IDLE

            if (agent.hp <= 0) {
                agent.animState = AnimState.DEAD;
                continue;
            }

            if (agent.stunTimer > 0 || agent.banished || agent.fearTimer > 0) {
                agent.animState = AnimState.STUN;
                continue;
            }

            // Hit reaction has high priority but short duration
            if (agent.hitFlashTimer > 0.05) {
                agent.animState = AnimState.HIT;
                continue;
            }

            if (agent.castingSkillIdx !== -1) {
                agent.animState = AnimState.ATTACK;
                continue;
            }

            if (agent.isMoving && agent.path.length > 0) {
                agent.animState = AnimState.MOVE;
                continue;
            }

            // Default State
            agent.animState = agent.target ? AnimState.COMBAT_IDLE : AnimState.IDLE;
        }
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, GameEventType, AnimState, SceneTheme, Hex, MovementType, LogActionType, HexLayout, GroundHazard, GlobalSessionState } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig } from "./utils";
import { DEFAULT_HEX_LAYOUT } from "../constants";
import { Agent, SpecialVisualStatus } from "./core/Agent";
import { MovementSystem } from "./systems/movement";
import { PhysicsSystem } from "./systems/PhysicsSystem"; 
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { HazardSystem } from "./systems/HazardSystem"; 
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { AnnouncerSystem } from "./systems/AnnouncerSystem"; 
import { DirectorSystem } from "./systems/DirectorSystem"; 
import { BattleLogger } from "./systems/BattleLogger"; 
import { TimeSystem } from "./systems/TimeSystem"; 
import { VictorySystem } from "./systems/VictorySystem"; 
import { ZoneSystem } from "./systems/ZoneSystem"; 
import { EventBus } from "./events/EventBus";
import { EventPool } from "./events/GameEventPool"; 
import { CooldownSystem } from "./systems/status/CooldownSystem";
import { EffectSystem } from "./systems/status/EffectSystem";
import { ControlSystem } from "./systems/status/ControlSystem";
import { AnimationSystem } from "./systems/AnimationSystem";
import { SequenceSystem } from "./systems/visuals/SequenceSystem"; 
import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];
    public projectiles: Projectile[] = [];

    private _entityCounter: number = 0;

    public state = {
        director: { focusTimer: 0, priorityTimer: 0, targetId: null as string | null },
        hazards: new Map<string, GroundHazard>(),
        victory: { victoryTimer: 0, winningTeam: null as Team | null, isFinishing: false },
        time: { battleTime: 0, timeScale: 1.0, targetTimeScale: 1.0 }
    };

    public sessionState: GlobalSessionState = {
        killStreaks: new Map(),
        firstBloodTriggered: false,
        directorTargetId: null,
        directorTimer: 0,
        directorPriorityTimer: 0
    };

    get hazards(): Map<string, GroundHazard> { return this.state.hazards; }
    get battleTime(): number { return this.state.time.battleTime; }
    set battleTime(v: number) { this.state.time.battleTime = v; }
    get timeScale(): number { return this.state.time.timeScale; }
    set timeScale(v: number) { this.state.time.timeScale = v; }
    get targetTimeScale(): number { return this.state.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.state.time.targetTimeScale = v; }
    get victory() { return this.state.victory; }

    get directorTargetId(): string | null { return this.state.director.targetId; }
    get mapKeys(): Set<string> { return this.map.mapKeys; }
    get obstacles(): Map<string, string> { return this.map.obstacles; }
    get agentMap(): Map<number, Agent> { return this.map.agentMap; }
    get logs(): LogEntry[] { return this.logger.logs; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer; 

    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    public screenAspect: number = 1.77;

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0, layout: DEFAULT_HEX_LAYOUT };
    public currentScene: SceneTheme = SCENE_DB[0];
    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public movement: MovementSystem = new MovementSystem();
    public physics: PhysicsSystem = new PhysicsSystem(); 
    public combat: CombatSystem = new CombatSystem();
    public map: MapSystem = new MapSystem();
    public hazardSystem: HazardSystem = new HazardSystem();
    public ai: AISystem = new AISystem();
    public agentManager: AgentManager = new AgentManager();
    public announcer: AnnouncerSystem = new AnnouncerSystem(); 
    public director: DirectorSystem = new DirectorSystem();
    public logger: BattleLogger = new BattleLogger(); 
    public victorySystem: VictorySystem = new VictorySystem(); 
    public zones: ZoneSystem = new ZoneSystem(); 
    public cooldowns: CooldownSystem = new CooldownSystem();
    public effects: EffectSystem = new EffectSystem();
    public controls: ControlSystem = new ControlSystem();
    public animation: AnimationSystem = new AnimationSystem();
    public timeSystem: TimeSystem = new TimeSystem();

    constructor() {
        this.map.randomizeEnvironment(this);
    }

    public nextId(prefix: string = 'ENT'): string {
        this._entityCounter++;
        return `${prefix}-${this._entityCounter.toString().padStart(4, '0')}`;
    }

    public addAgent(team: Team, q: number, r: number, hpOverride?: number, roleOverride?: Role) { 
        return this.agentManager.addAgent(this, team, q, r, hpOverride, roleOverride); 
    }
    public isValid(q: number, r: number) { return this.map.isValid(q, r); }
    public isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    public isValidHash(h: number) { return this.map.isValidHash(h); }
    public hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    public hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    public getTerrainHeight(q: number, r: number) { return this.map.getTerrainHeight(q, r); }

    public randomizeEnvironment() { 
        this.state.hazards.clear(); 
        this.bus.emit('ENV_UPDATE', {});
        this.map.randomizeEnvironment(this); 
    }

    public rebuildMap() { 
        this.state.hazards.clear();
        this.bus.emit('ENV_UPDATE', {});
        this.map.rebuildMap(this); 
    }

    public removeAgent(q: number, r: number) {
        const agent = this.map.getAgentAt(q, r);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.map.unregisterAgent(agent);
        }
    }

    public getAgentAt(q: number, r: number): Agent | undefined {
        return this.map.getAgentAt(q, r);
    }

    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.map.updateAgentPosition(agent, newQ, newR);
    }

    public pushEvent(type: GameEventType, pos: {x: number, y: number}, opts: any = {}) {
        const evt = EventPool.get(type, pos, opts);
        if (type === 'KILL' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 2.5);
        } else if (type === 'CAST_START' && opts.skill?.tag === 'ULT' && opts.sourceId) {
            this.director.forceFocus(this, opts.sourceId, 3.5); 
        }
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.state.time.battleTime = 0;
            this.logger.clear();
            this.victorySystem.reset(this);
            this.sessionState.killStreaks.clear();
            this.sessionState.firstBloodTriggered = false;
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.map.clearAgents();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) this.map.registerAgent(a);
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victorySystem.reset(this);
        this.state.time.battleTime = 0;
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.director.reset(this);
        this.sessionState.killStreaks.clear();
        this.sessionState.firstBloodTriggered = false;
        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => this.skillDB.find(s => s.id === id) || null);
            this.map.registerAgent(a);
        });
        this.projectiles = [];

        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this._entityCounter = 0; 
        this.agents = [];
        this.projectiles = [];
        this.map.clearAgents();
        this.state.hazards.clear(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.director.reset(this);
        this.logger.clear();
        this.victorySystem.reset(this); 
        this.state.time.timeScale = 1.0;
        this.state.time.targetTimeScale = 1.0;
        this.sessionState.killStreaks.clear();
        this.sessionState.firstBloodTriggered = false;

        SequenceSystem.clear(); 

        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 
        this.bus.emit('GAME_CLEAR', {});
    }

    public tick(dt: number) {
        if (!this.isRunning) return;
        this.timeSystem.update(dt, this);
        this.events.length = 0; 
        this.director.update(this, dt);
        this.zones.update(this); 
        if (this.victorySystem.check(this)) {
            this.victorySystem.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }
        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        this.physics.update(dt, this);
        for (const a of this.agents) {
            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);
            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }
            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }
        this.combat.update(dt, this);
        this.hazardSystem.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);

        // SSOT Enforcement: Animation state is derived last
        this.animation.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number): number {
        return this.movement.getEffectiveRange(a, targetQ, targetR, baseRange, this);
    }

    public calculateOptimalTarget(source: Agent, skill: Skill) {
        return this.movement.calculateOptimalTarget(source, skill, this);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, speedMult: number = 1.0): NodeState {
        return this.movement.moveAgentToHex(a, targetHex, r, this, speedMult);
    }

    public initiateCast(a: Agent, skillIdx: number): NodeState {
        return this.combat.initiateCast(a, skillIdx, this);
    }

    public updateTarget(a: Agent) {
        this.movement.updateTarget(a, this);
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    public hp: number = 100;
    public maxHp: number = 100;
    public shield: number = 0;
    public maxShield: number = 0;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0;
    public moveSpeedMult: number = 1.0;
    public jump: number = 1;
    public weight: number = 1;
    public movementType: MovementType = MovementType.GROUND;

    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0;
    public curCDs: number[] = [0, 0, 0];

    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;
    public facing: number = 1;
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    public aiUpdateTimer: number = 0;
    public aiUpdateInterval: number = 0.3;

    public trailHistory: {x: number, y: number, z: number}[] = [];

    public stunTimer: number = 0;
    public stunMax: number = 0;

    public banishTimer: number = 0;
    public banishMax: number = 0;

    public silenceTimer: number = 0;
    public silenceMax: number = 0;

    public banished: boolean = false;

    public rootTimer: number = 0;
    public fearTimer: number = 0;
    public tauntTimer: number = 0;
    public blindTimer: number = 0;
    public tauntTargetId: string | null = null;

    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    public drStacks: Record<string, number> = {};
    public drTimers: Record<string, number> = {};

    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public hitFlashTimer: number = 0;

    public physics = {
        x: 0, y: 0, z: 0,
        vx: 0, vy: 0, vz: 0,
        angle: 0, vAngle: 0
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(id: string, team: Team, q: number, r: number, config: MapConfig) {
        this.id = id;
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.aiUpdateInterval = 0.2 + Math.random() * 0.2; 

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.shield = 0;
        this.maxShield = 0;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0;
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.stunMax = 0;
        this.banishTimer = 0;
        this.banishMax = 0;
        this.silenceTimer = 0;
        this.silenceMax = 0;
        this.rootTimer = 0;
        this.fearTimer = 0;
        this.tauntTimer = 0;
        this.blindTimer = 0;
        this.tauntTargetId = null;

        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.drStacks = {};
        this.drTimers = {};

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5;

        this.target = null;
        this.targetHex = null;

        this.aiUpdateTimer = Math.random() * 0.5;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
        this.trailHistory = [];
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils } from "../utils";
import { Hex, NodeState } from "../../types";
import { Pathfinder } from "../ai/Pathfinder";
import { TargetingSystem } from "../ai/TargetingSystem";
import { MotionEngine } from "./movement/MotionEngine";
import { StackingResolver } from "./movement/StackingResolver";

export class MovementSystem {
    public pathfinder: Pathfinder;
    public targeting: TargetingSystem;
    private stackingResolver: StackingResolver;

    constructor() {
        this.pathfinder = new Pathfinder();
        this.targeting = new TargetingSystem();
        this.stackingResolver = new StackingResolver();
    }

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        return this.targeting.getEffectiveRange(a, targetQ, targetR, baseRange, engine);
    }

    public updateTarget(a: Agent, engine: GameEngine) {
        this.targeting.updateTarget(a, engine);
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine) {
        return this.targeting.calculateOptimalTarget(source, skill, engine);
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        MotionEngine.updateMovement(a, dt, engine);
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        const effRange = this.targeting.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        const distToTarget = HexUtils.dist(a, targetHex);

        // 1. 如果已經在射程內，停止移動並返回成功
        if (distToTarget <= effRange) {
            if (a.isMoving) {
                a.isMoving = false;
                a.path = [];
            }
            return NodeState.SUCCESS;
        }

        // 2. 如果正在移動，檢查目的地是否需要更新
        if (a.isMoving && a.path.length > 0) {
            const currentGoal = a.path[a.path.length - 1];
            // 如果目標點沒變，繼續執行當前移動
            if (currentGoal.q === targetHex.q && currentGoal.r === targetHex.r) {
                a.moveSpeedMult = speedMult;
                return NodeState.RUNNING;
            }
            // 目標點變了，不中斷當前物理位移，但在下一個 Tick 重新計算路徑
        }

        // 3. 尋找新路徑
        let path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, false, engine, this.targeting);
        if (path.length === 0 && distToTarget > effRange) {
            // 如果被單位堵住，嘗試無視單位尋路（擠過去）
            path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, true, engine, this.targeting);
        }

        if (path.length > 0) {
            const next = path[0];
            // 檢查下一格是否被地形完全阻擋
            if (engine.isBlocked(next.q, next.r, a.id, a.movementType)) {
                return NodeState.RUNNING;
            }

            // 更新路徑，保留移動狀態
            a.path = path;
            a.trajectory = path;
            if (!a.isMoving) {
                a.isMoving = true;
                a.moveProgress = 0;
            }
            a.moveSpeedMult = speedMult;
            return NodeState.RUNNING;
        }

        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this.stackingResolver.resolve(engine);
    }
}

import { Agent, GameEngine } from "../../game";

export class CastingEngine {

    public updateCasting(a: Agent, dt: number, engine: GameEngine, onComplete: (a: Agent) => void) {
        // 1. 硬控場檢查 (Interrupt Priority)
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. 動態轉向 (Sticky Targeting)：確保攻擊動作始終朝向目標
        if (a.target) {
            const dx = a.target.px - a.px;
            if (Math.abs(dx) > 2) { // 避免高頻抖動
                a.facing = dx > 0 ? 1 : -1;
            }
        }

        // 3. 詠唱進度積分
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            onComplete(a);
            this.resetCaster(a);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                // 計算進度比：進度越高，中斷爆炸越強
                const progressPct = 1 - (a.castTimer / s.cast);

                engine.log(a, 'CC', '中斷', s.name, `詠唱被打斷 (進度: ${Math.floor(progressPct * 100)}%)`);

                // 傳遞精確的 3D 位置與進度參數，並補上 sourceId
                engine.events.push({ 
                    type: 'CAST_BREAK', 
                    pos: { x: a.px, y: a.py }, 
                    value: progressPct, // 這裡重用 value 傳遞進度
                    color: s.color, 
                    skill: s,
                    sourceId: a.id 
                });
            }
        }
        this.resetCaster(a);
    }

    private resetCaster(a: Agent) {
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, NodeState } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { CastingEngine } from "./combat/CastingEngine";
import { SkillExecutor } from "./combat/SkillExecutor";
import { HexUtils } from "../utils";
export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public castingEngine: CastingEngine;
    public skillExecutor: SkillExecutor;
    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.castingEngine = new CastingEngine();
        this.skillExecutor = new SkillExecutor();
    }
    public reset() {
        // Projectiles are cleared by the GameEngine root container
    }
    public initiateCast(a: Agent, skillIdx: number, engine: GameEngine): NodeState {
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;
        if (isHardCC) return NodeState.FAILURE;
        const skill = a.skills[skillIdx];
        if (!skill) return NodeState.FAILURE;
        if (a.silenceTimer > 0 && skill.tag !== 'BASIC') return NodeState.FAILURE;
        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = skillIdx;
            a.castTimer = skill.cast;
            a.castingAnimationTimer = skill.cast;
            a.btStatus = `詠唱 ${skill.tag}`;
            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;
            engine.log(a, 'CAST', '詠唱', targetName, `開始引導 ${skill.name} (需 ${skill.cast} 秒)`);
            // sourceId 必須傳遞，供 HUD 綁定文字
            engine.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: skill });

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }
    public update(dt: number, engine: GameEngine) {
        engine.agents.forEach(a => {
            // 修正：如果單位已死但仍在詠唱，允許進入 updateCasting 進行中斷處理
            if (a.hp <= 0 && a.castingSkillIdx === -1) return;

            if (a.castingSkillIdx !== -1) {
                this.castingEngine.updateCasting(a, dt, engine, (agent) => {
                    this.completeCast(agent, engine);
                });
            }
        });
        this.projectileSystem.update(dt, engine, this.skillExecutor);
    }
    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             this.spawnProjectile(a, s, engine);
        } else {
            this.skillExecutor.executeInstantSkill(a, s, engine);
        }
    }
    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }
}

import { Agent, GameEngine } from "../game";
import { MovementType } from "../../types";
import { HexUtils } from "../utils";
import { PHYSICS } from "../../constants";

export class PhysicsEngine {
    public static applyImpulse(target: Agent, origin: {x: number, y: number}, force: number, randomness: number = 0) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const effectiveForce = Math.min(PHYSICS.TERMINAL_VELOCITY_IMPULSE, Math.max(50, force));
        let vx = 0, vy = 0;
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }
        target.physics.vx += vx;
        target.physics.vy += vy;

        target.physics.vAngle += (Math.random() - 0.5) * 10.0; 

        if (randomness > 0) target.physics.vAngle += (Math.random() - 0.5) * randomness;
    }

    public update(a: Agent, dt: number, engine: GameEngine) {
        if (a.fullyDead) return;
        const isDead = a.hp <= 0;

        const stiffness = isDead ? 0 : PHYSICS.STIFFNESS_ALIVE * 1.2;
        const damping = PHYSICS.DAMPING_ALIVE * 1.1; 

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        if (isFlying && !isDisabled) {
            const hoverHeight = 55, hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92;
        } else if (isAirborne || a.physics.z > 0.1) {
            a.physics.vz -= PHYSICS.GRAVITY * dt;
        }

        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        const speedSq = a.physics.vx*a.physics.vx + a.physics.vy*a.physics.vy;
        if (speedSq > 10000 || (a.movementType === MovementType.FLYING && a.hp > 0)) {
            a.trailHistory.push({ x: a.px + a.physics.x, y: a.py + a.physics.y, z: a.physics.z });
            if (a.trailHistory.length > 10) a.trailHistory.shift();
        } else if (a.trailHistory.length > 0) {
            a.trailHistory.shift();
        }

        if (a.physics.z < 0) {
            a.physics.z = 0;
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;
                    a.hp = Math.max(0, a.hp - rawDmg);
                    engine.events.push({ type: 'DAMAGE', pos: {x: a.px, y: a.py}, value: -rawDmg, color: '#ef4444', text: "墜落" });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg}`);

                    engine.bus.emit('CAMERA_SHAKE', { intensity: pct * 0.5 });

                    if (a.hp <= 0) {
                        engine.agentManager.handleDeadState(a, engine);
                    } else {
                        // SSOT: Set visual timer instead of imperative setAnim
                        a.hitFlashTimer = 0.2; 
                    }
                }
                a.physics.vz = -a.physics.vz * 0.3;
                a.physics.vx *= 0.5; a.physics.vy *= 0.5; a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px, dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            if (speedSq < 5000) {
                if (distSq > 0.5) {
                    const driftSpeed = PHYSICS.DRIFT_SPEED * dt; 
                    a.px += dx * driftSpeed; a.py += dy * driftSpeed;
                    if (distSq < 2) { a.px = targetPos.x; a.py = targetPos.y; }
                } else {
                    a.px = targetPos.x; a.py = targetPos.y;
                }
            }
        }
    }
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";

export class AgentManager {
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number, roleOverride?: Role): Agent | null {
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const id = engine.nextId(team === Team.BLUE ? 'BLU' : 'RED');
        const a = new Agent(id, team, q, r, engine.mapConfig);

        if (roleOverride) {
            a.role = roleOverride;
        } else {
            const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
            a.role = allRoles[Math.floor(Math.random() * allRoles.length)];
        }

        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.spawnTimer = 0.5;
        engine.events.push({ type: 'SPAWN', pos: { x: a.px, y: a.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            // SSOT: Initial state handled by AnimationSystem
        }

        engine.agents.push(a);
        engine.map.registerAgent(a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.px, y: a.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            // SSOT: AnimationSystem will see hp <= 0 and set AnimState.DEAD
            engine.map.unregisterAgent(a);
            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";
import { HEX_SIZE } from "../../constants";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "IsFeared": (a) => a.fearTimer > 0, 

    "HasTarget": (a, engine) => {
        if (a.aiUpdateTimer <= 0) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; 
        }
        if (a.target && (a.target.hp <= 0 || a.target.banished)) {
            a.target = null;
            engine.updateTarget(a);
        }
        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        let cd = a.curCDs[idx];
        if (isNaN(cd)) cd = 0;

        const tolerance = (s.tag === 'BASIC') ? 0.15 : 0.05;
        const isOnCD = cd > tolerance; 

        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            return true;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const gridDist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        if (gridDist > effRange + 0.6) return false;

        if (effRange <= 1.0) {
            const startPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            let endPx;
            if (a.targetHex) endPx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig);
            else endPx = { x: a.target!.px, y: a.target!.py };
            const dx = startPx.x - endPx.x;
            const dy = startPx.y - endPx.y;
            const pxDist = Math.sqrt(dx*dx + dy*dy);

            if (pxDist > HEX_SIZE * 2.8) return false;
        }

        return true;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        if (a.isMoving && a.path.length === 0) {
            a.isMoving = false;
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;
        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;
        let dest = a.targetHex || (a.target ? {q: a.target.q, r: a.target.r} : null);

        if (dest) {
            if (a.q === dest.q && a.r === dest.r) return NodeState.SUCCESS;
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot; 
        const skill = a.skills[idx] || a.skills[2];

        if (!skill || !a.target) return NodeState.FAILURE;

        const effRange = engine.getEffectiveRange(a, a.target.q, a.target.r, skill.range);
        const dist = HexUtils.dist(a, a.target);

        if (dist <= effRange) {
            if (a.isMoving) {
                a.isMoving = false;
                a.path = [];
            }
            const dx = a.target.px - a.px;
            if (Math.abs(dx) > 1) a.facing = dx > 0 ? 1 : -1;

            a.btStatus = "戰鬥鎖定";
            // SSOT: AnimationSystem derives COMBAT_IDLE from having a target
            return NodeState.SUCCESS;
        }

        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `追蹤 ${a.target.id}`;
        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

import { Agent, GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); 
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            // SSOT: AnimationSystem will set STUN
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            if (agent.rootTimer <= 0) {
                if (!agent.isMoving && agent.aiUpdateTimer <= 0) {
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        const result = engine.moveAgentToHex(agent, targetHex, 0, 1.5);
                        if (result === 'R') { 
                            agent.aiUpdateTimer = 0.5; 
                        } else {
                            agent.aiUpdateTimer = 0.8; 
                        }
                    } else {
                        agent.aiUpdateTimer = 0.8; 
                    }
                }
            } else {
                agent.isMoving = false;
                agent.path = [];
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        // Removed default idle setting. AnimationSystem handles IDLE/COMBAT_IDLE.

        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                const pz = agent.physics.z + 45;

                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('BURN', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill } from "../../../types";
import { Vector, HexUtils } from "../../utils";

export const CCManager = {

    applyCC(
        source: Agent, 
        target: Agent, 
        skill: Skill, 
        type: string | undefined, 
        dur: number | undefined, 
        force: number | undefined, 
        origin: {x: number, y: number} | undefined, 
        engine: GameEngine
    ) {
        if (!type || type === 'NONE') return;

        const { effectiveDuration, isImmune } = this.checkDR(target, type, dur || 0);

        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫", color: "#9ca3af" });
            return;
        }

        let statusText = "";
        let statusColor = "#fff";

        switch (type) {
            case 'STUN':
                if (effectiveDuration > target.stunTimer) {
                    target.stunTimer = effectiveDuration;
                    target.stunMax = effectiveDuration;
                }
                target.isMoving = false;
                // SSOT: AnimState.STUN is derived from stunTimer
                statusText = "暈眩"; statusColor = "#facc15";

                if (skill.element === 'ICE') target.visualStatus = 'FROZEN';
                break;

            case 'SILENCE':
                if (effectiveDuration > target.silenceTimer) {
                    target.silenceTimer = effectiveDuration;
                    target.silenceMax = effectiveDuration;
                }
                statusText = "沉默"; statusColor = "#94a3b8";
                break;

            case 'BANISH':
                if (effectiveDuration > target.banishTimer) {
                    target.banishTimer = effectiveDuration;
                    target.banishMax = effectiveDuration;
                }
                target.banished = true;
                target.isMoving = false;
                // SSOT: AnimState.STUN is derived from banished state

                statusText = "放逐"; statusColor = "#c084fc";

                if (skill.specialVisualStatus) target.visualStatus = skill.specialVisualStatus;
                break;

            case 'ROOT':
                if (effectiveDuration > target.rootTimer) target.rootTimer = effectiveDuration;
                target.isMoving = false;
                statusText = "禁錮"; statusColor = "#fbbf24";
                break;

            case 'FEAR':
                if (effectiveDuration > target.fearTimer) target.fearTimer = effectiveDuration;
                statusText = "恐懼"; statusColor = "#a855f7";
                break;

            case 'TAUNT':
                if (effectiveDuration > target.tauntTimer) {
                    target.tauntTimer = effectiveDuration;
                    target.tauntTargetId = source.id; 
                }
                statusText = "嘲諷"; statusColor = "#ef4444";
                break;

            case 'BLIND':
                if (effectiveDuration > target.blindTimer) target.blindTimer = effectiveDuration;
                statusText = "致盲"; statusColor = "#cbd5e1";
                break;

            case 'SHIELD':
                const amount = force || 50;
                target.shield += amount;
                target.maxShield = Math.max(target.maxShield, target.shield);
                statusText = "護盾"; statusColor = "#bae6fd";
                break;

            case 'KNOCKBACK':
            case 'PULL':
                const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
                if (result.applied) {
                    statusText = type === 'PULL' ? "牽引" : "擊退";
                    // SSOT: Trigger hit flash to cause reaction
                    if (target.hp > 0) target.hitFlashTimer = 0.2;
                    target.physics.vz += 150; 
                }
                break;

            case 'DOT':
                target.dotDmg = force || 10;
                target.dotTimer = effectiveDuration;
                statusText = "中毒"; statusColor = "#10b981";
                break;

            case 'HOT':
                target.hotVal = force || 10;
                target.hotTimer = effectiveDuration;
                statusText = "再生"; statusColor = "#86efac";
                break;
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
            engine.log(source, 'CC', type, target.id, `施加 ${statusText} (${effectiveDuration.toFixed(1)}s)`);
        }
    },

    checkDR(target: Agent, type: string, baseDuration: number) {
        const isHardCC = ['STUN', 'SILENCE', 'BANISH', 'FEAR', 'TAUNT', 'ROOT'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false };

        const stacks = target.drStacks[type] || 0;
        const multiplier = Math.pow(0.5, stacks); 

        if (multiplier < 0.2) return { effectiveDuration: 0, isImmune: true };

        target.drStacks[type] = stacks + 1;
        target.drTimers[type] = 10.0; 

        return { effectiveDuration: baseDuration * multiplier, isImmune: false };
    },

    calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 

        const tilesToPush = Math.max(0, rawForce - resistance);
        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1); 

        let currentH = {q: target.q, r: target.r};
        let finalH = currentH;

        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN: any = null;
            let bestDot = -2.0; 

            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));

                const dot = nDir.x * vector.x + nDir.y * vector.y;
                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }

            if (bestN) {
                if (!engine.map.isValid(bestN.q, bestN.r) || engine.map.hasObstacle(bestN.q, bestN.r)) break; 
                if (engine.getAgentAt(bestN.q, bestN.r)) break; 

                const curHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > curHeight + 24) break; 

                currentH = bestN;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }
};

import { Agent, GameEngine } from "../../game";
import { Skill } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";
import { COMBAT_PARAM } from "../../../constants";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];

        // 1. 確定施法中心點
        let targetHex;
        if (skill.range === 0) {
            targetHex = { q: source.q, r: source.r };
        } else {
            targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});
        }

        // 2. 獲取受影響區域
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);
        const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
        const origin = { x: p.x, y: p.y };

        // 3. 判定受擊目標
        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    // 敵我識別
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });
            HazardManager.spawnHazards(source, impactCells, skill, engine);
        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 4. 結算效果
        targets.forEach(target => {
            this.resolveHit(source, target, skill, origin, engine);
        });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!target || target.hp <= 0 || target.banished) return;

        // A. Damage Calculation
        const result = DamageCalculator.calculate(source, target, skill);

        if (result.isMiss) {
            engine.events.push({ type: 'DAMAGE', pos: {x: target.px, y: target.py}, text: "MISS", color: '#9ca3af' });
            return;
        }

        if (result.shieldAbsorb > 0) {
            engine.events.push({ type: 'DAMAGE', pos: {x: target.px, y: target.py}, value: -Math.floor(result.shieldAbsorb), color: '#bae6fd', text: "ABSORB" });
        }

        if (result.finalValue !== 0) {
            target.hp = Math.max(0, Math.min(target.maxHp, target.hp + result.finalValue));

            // Visual Event
            const isHeal = result.finalValue > 0;
            const evtType = isHeal ? 'HEAL' : 'DAMAGE';
            const color = isHeal ? '#86efac' : (result.isCrit ? '#ef4444' : skill.color);

            engine.events.push({ 
                type: evtType, 
                pos: {x: target.px, y: target.py}, 
                value: Math.abs(Math.floor(result.finalValue)), 
                color,
                skill,
                targetId: target.id,
                sourceId: source.id
            });

            // SSOT: Trigger Animation System
            if (!isHeal) {
                target.hitFlashTimer = COMBAT_PARAM.HIT_FLASH_DURATION;

                // Physics Impulse (Small nudge on hit)
                if (origin && !skill.ccType) {
                    PhysicsEngine.applyImpulse(target, origin, COMBAT_PARAM.HIT_IMPULSE_MIN);
                }
            }
        }

        // B. Secondary Effects (Vamp, Mana)
        if (result.vampAmount > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#be123c', text: "VAMP" });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            engine.events.push({ type: 'DAMAGE', pos: {x: target.px, y: target.py}, value: result.manaBurn, color: '#8b5cf6', text: "BURN" });
        }
        if (result.manaRestore > 0) {
            target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
            engine.events.push({ type: 'HEAL', pos: {x: target.px, y: target.py}, value: result.manaRestore, color: '#60a5fa', text: "MP" });
        }

        // C. Crowd Control (CC) Application
        if (skill.ccType && skill.ccType !== 'NONE') {
            CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        }
        if (skill.ccType2 && skill.ccType2 !== 'NONE') {
            CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);
        }

        // D. Death Check
        if (target.hp <= 0) {
            engine.agentManager.handleDeadState(target, engine);
            if (result.isExecute) {
                engine.log(source, 'HIT', '斬殺', target.id, `造成 ${Math.abs(result.finalValue)} 傷害 (斬殺)`);
            } else {
                engine.pushEvent('KILL', {x: target.px, y: target.py}, { sourceId: source.id, targetId: target.id });
            }
        }
    }
}

