import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE } from "../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../math/TrajectoryMath";
import { VisualMath } from "../../math/VisualMath";
import { SkillExecutor } from "./SkillExecutor";
import { HazardManager } from "./HazardManager";
import { HEX_SIZE } from "../../../constants";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            // 1. Advance Time
            const dtStep = dt / p.totalDuration;
            p.t = Math.min(1.0, p.t + dtStep);

            // 2. Calculate True 3D Position (SSOT)
            // Logic now knows exactly where the projectile is, including height (Arc) and wobble.
            this.updatePosition(p);

            // 3. Impact Check
            if (p.t >= 1.0) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            }
        }
    }

    private updatePosition(p: Projectile) {
        const start: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
        const end: Point3D = { x: p.endX, y: p.endY, z: p.endZ };
        const traj = p.trajectoryInfo;

        let pos: Point3D;

        if (traj.type === 'ARC') {
            const arcH = Math.min(traj.arcHeight || 150, Math.max(30, p.totalDist * 0.35));
            pos = TrajectoryMath.parabolic(start, end, p.t, arcH);
        } 
        else if (traj.type === 'WOBBLE') {
            pos = TrajectoryMath.wobble(start, end, p.t, traj.wobbleAmp || 15, traj.wobbleFreq || 2);
        } 
        else {
            pos = TrajectoryMath.linear(start, end, p.t);
        }

        p.x = pos.x;
        p.y = pos.y;
        p.z = pos.z;
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = { x: p.endX, y: p.endY };

        if (p.skill.type === 'AOE') {
            const radiusGrid = p.skill.aoeRadius || 1;
            const radiusPx = radiusGrid * HEX_SIZE + 10;
            const radiusSq = radiusPx * radiusPx;

            const hitHex = VisualMath.resolveTargetPoint(p.targetId, engine); // Approximate

            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    const targetPx = VisualMath.getUnitAnchor(t, engine);
                    const dx = targetPx.x - hitPos.x;
                    const dy = targetPx.y - hitPos.y;
                    const distSq = dx*dx + dy*dy;

                    if (distSq <= radiusSq) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });

            // Note: spawnHazards requires Hexes, we need to convert hitPos to Hex
            // This is slightly expensive but accurate
            if (source) {
                // TODO: Optimize getting hexes in range
                // For now, reuse the existing logic in HazardManager which takes center hex
                // We need to pass the target hex from the original skill context if possible
                // But p.targetId might be generic.
                // Fallback:
                // HazardManager.spawnHazards(source, [HexUtils.fromPx(...)], ...);
            }

            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        const targetPoint = VisualMath.resolveTargetPoint(targetId, engine);

        const dx = targetPoint.x - launchPoint.x;
        const dy = targetPoint.y - launchPoint.y;
        const totalDist = Math.sqrt(dx*dx + dy*dy);
        const speed = skill.projectileSpeed || 800;

        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true;
        p.id = engine.nextId('PRJ');
        p.sourceId = source.id;
        p.team = source.team;
        p.skill = skill;
        p.t = 0;
        p.totalDuration = Math.max(0.1, totalDist / speed);
        p.startX = launchPoint.x; p.startY = launchPoint.y; p.startZ = launchPoint.z;
        p.endX = targetPoint.x; p.endY = targetPoint.y; p.endZ = targetPoint.z;
        p.totalDist = totalDist;
        p.targetId = targetId;
        p.trail = [];

        // SSOT: Embed Trajectory Configuration at Spawn Time
        // This ensures Physics and Rendering use the exact same definition
        const visualKey = skill.visualProjectileEffect || skill.visual || 'BOLT';
        const def = PROJECTILE_VISUALS[visualKey] || DEFAULT_PROJECTILE;

        p.trajectoryInfo = {
            type: def.trajectory,
            arcHeight: def.arcHeight,
            wobbleFreq: def.wobbleFreq,
            wobbleAmp: def.wobbleAmp,
            spinSpeed: def.spinSpeed,
            spriteKey: def.spriteKey || visualKey,
            scale: def.scale
        };

        // Initialize Position immediately
        this.updatePosition(p);

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill, targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }

    private createEmptyProjectile(): Projectile {
        return { 
            id: '', active: false, createdAt: 0, lifespan: 0, 
            x: 0, y: 0, z: 0, t: 0, totalDuration: 0,
            startX: 0, startY: 0, startZ: 0, endX: 0, endY: 0, endZ: 0, totalDist: 0,
            targetId: '', targetPos: {x: 0, y: 0}, 
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [],
            trajectoryInfo: { type: 'LINEAR' }
        };
    }
}

import { GameEngine } from "../../../game";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath, Point3D } from "../../../math/VisualMath";
import { ISO_SCALE_Y } from "../../../../constants";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const traj = p.trajectoryInfo;

            // 1. Use Logic Position (SSOT)
            // No more TrajectoryMath.calculate here. Logic has already done it.
            const current3D = { x: p.x, y: p.y, z: p.z };

            // 2. Calculate Visual Angle (Derivative)
            // We still need the formula to calculate the angle tangent
            const getPosAt = (t: number) => {
                const start: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
                const end: Point3D = { x: p.endX, y: p.endY, z: p.endZ };
                if (traj.type === 'ARC') return TrajectoryMath.parabolic(start, end, t, traj.arcHeight || 150);
                if (traj.type === 'WOBBLE') return TrajectoryMath.wobble(start, end, t, traj.wobbleAmp || 15, traj.wobbleFreq || 2);
                return TrajectoryMath.linear(start, end, t);
            };

            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, p.t, ISO_SCALE_Y);

            // 3. Project to Screen
            const transOffset = VisualMath.getTransitionOffset(current3D.x, current3D.y, engine.mapConfig, transitionT, transitionPhase);
            const visY = VisualMath.getIsoVisualY(current3D.y, current3D.z) + transOffset;

            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = current3D.y; 
            op.z = 5000 + current3D.z; 

            op.pVisX = current3D.x;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = traj.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = traj.spinSpeed ? (p.t * p.totalDuration * traj.spinSpeed) : 0;
            op.pScale = traj.scale || 1.0; 

            // 4. Trails (Calculated purely visually backwards from SSOT position)
            op.pTrail = [];
            // Use visuals DB or default for trail length, as it's purely cosmetic and not in SSOT Logic state
            // Optimization: Just use a standard length or infer from type
            const trailSamples = p.skill.tag === 'ULT' ? 20 : 10;

            if (trailSamples > 0) {
                const step = 0.015; 
                for (let j = 1; j <= trailSamples; j++) {
                    const tPast = Math.max(0, p.t - j * step);
                    // We must recalculate past positions as we don't store history in Logic
                    const past3D = getPosAt(tPast);
                    const pOffset = VisualMath.getTransitionOffset(past3D.x, past3D.y, engine.mapConfig, transitionT, transitionPhase);
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + pOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { Agent, GameEngine } from "./game";
import { Hex, GameEvent, Skill } from "../types";
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";
import { RenderPipeline } from "./renderers/RenderPipeline";
import { StatusOrchestrator } from "./renderers/status/StatusOrchestrator"; 
import { SequenceSystem } from "./systems/visuals/SequenceSystem"; 
import type { GameRenderer } from "./renderer";

export { Camera };

export class GameRenderer {
    public grid: GridSystem = new GridSystem();
    public vfx: VFXSystem = new VFXSystem();
    public vfxRenderer: VFXRenderer = new VFXRenderer();
    public unit: UnitRenderSystem = new UnitRenderSystem();
    public statusOrchestrator: StatusOrchestrator = new StatusOrchestrator(); 
    public hud: HUDSystem = new HUDSystem();
    public camera: CameraSystem = new CameraSystem();
    private eventListener: VisualEventListener = new VisualEventListener();
    private pipeline: RenderPipeline = new RenderPipeline(this);

    private boundEngine: GameEngine | null = null;

    // Decoupling: Explicit binding allows us to subscribe to events
    public bind(engine: GameEngine) {
        if (this.boundEngine === engine) return;

        // Unbind previous if exists
        if (this.boundEngine) {
            this.boundEngine.bus.off('GAME_RESET', this.handleReset);
            this.boundEngine.bus.off('GAME_CLEAR', this.handleReset);
            this.boundEngine.bus.off('ENV_UPDATE', this.handleReset);
            this.boundEngine.bus.off('CAMERA_SHAKE', this.handleShake);
            this.boundEngine.bus.off('CAMERA_MOVE', this.handleCameraMove);
        }

        this.boundEngine = engine;

        // Bind new
        this.boundEngine.bus.on('GAME_RESET', this.handleReset);
        this.boundEngine.bus.on('GAME_CLEAR', this.handleReset);
        this.boundEngine.bus.on('ENV_UPDATE', this.handleReset);
        this.boundEngine.bus.on('CAMERA_SHAKE', this.handleShake);
        this.boundEngine.bus.on('CAMERA_MOVE', this.handleCameraMove);
    }

    private handleReset = () => {
        this.reset();
    }

    private handleShake = (data: { intensity: number }) => {
        this.camera.addTrauma(data.intensity);
    }

    private handleCameraMove = (data: { x: number, y: number, zoom: number }) => {
        this.camera.setDirectorTarget(data.x, data.y, data.zoom);
    }

    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
        this.grid.reset(); 
    }

    public setTransitionPhase(phase: 'IN' | 'OUT' | 'IDLE') { 
        this.pipeline.setTransitionPhase(phase); 
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number { return this.grid.getTerrainHeight(q, r, engine); }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2, cy = height / 2;
        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;
        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    public update(dt: number, engine: GameEngine, externalCameraRef?: any): void {
        // 1. Camera Update (Always RealTime for smoothness)
        this.camera.update(dt);

        if (externalCameraRef?.current) {
            externalCameraRef.current.x = this.camera.x;
            externalCameraRef.current.y = this.camera.y;
        }

        // 2. SSOT Time Calculation
        // Simulation Time Delta = Real DT * TimeScale (0 if paused)
        const simDt = engine.isRunning ? dt * engine.timeScale : 0;
        const battleTime = engine.battleTime; // SSOT from Logic

        // 3. Sequence System (Logic Driven)
        SequenceSystem.update(engine, this.vfx);

        // 4. Render Pipeline (Transitions)
        this.pipeline.update(dt, engine); 

        // 5. VFX System (Time Dilation Applied)
        // Ambience and Particles now move in sync with game speed (Bullet Time ready)
        this.vfx.update(
            simDt, 
            battleTime, 
            engine.currentScene.ambientType, 
            (x, y) => this.grid.getTerrainHeight(
                this.grid.getHexAtWorldPoint(x, y, engine)?.q || 0,
                this.grid.getHexAtWorldPoint(x, y, engine)?.r || 0,
                engine
            )
        );

        // 6. HUD System (Always RealTime, UI should not freeze)
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void { this.eventListener.process(events, engine, this.vfx, this.hud, this.grid, this.camera); }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, battleTime: number, realTime: number): void {
        this.pipeline.draw(ctx, engine, camera, highlight, fps, hoveredHex, hoveredSkill, battleTime, realTime);
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";
import { Point3D } from "../math/VisualMath";

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();

    public reset() { this.state.reset(); }

    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }

    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x; p.ty = end.y; p.tz = end.z;
        p.x = start.x; p.y = start.y; p.z = start.z;
        p.life = duration; p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; p.style = styleId; p.locked = true;
        this.state.particles.push(p);
    }

    /**
     * SSOT Update:
     * @param dt - Scaled Simulation Delta Time (0 if paused)
     * @param battleTime - Current Battle Time (for procedural shaders)
     */
    update(dt: number, battleTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            // Apply Time Dilation to Delays
            if (p.delay && p.delay > 0) { 
                p.delay -= dt; 
                continue; 
            }

            p.life -= dt;

            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop(); count--; continue;
            }

            if (p.locked) { 
                p.rotation += p.vRotation * dt; 
                continue; 
            }

            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX, dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) p.life = 0; 
            }

            VFXPhysics.update(p, dt, getTerrainHeight);
        }

        // Decals also respect time scale
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }

        this.ambience.update(dt, ambientType, this.state);
    }
}

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";
import { HexLayout } from "../../../../types";

// Static categorization for faster dispatch
const PROCEDURAL_SET = new Set(['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM', 'MAGIC_CIRCLE', 'BLACK_HOLE']);
const GROUND_PLANE_SET = new Set(['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'HEX_GLOW']);

/**
 * Unified Particle Dispatcher v9.0 (Time SSOT)
 */
export const ParticleRenderer = {

    drawSingleParticle(
        ctx: CanvasRenderingContext2D, 
        p: Particle, 
        drawX: number, 
        drawY: number, 
        progress: number, 
        isChaos: boolean, 
        layout: HexLayout,
        battleTime: number // SSOT: Received from RenderLoop
    ) {
        // 1. Vectorized Procedural Logic (Pillars, Domains, Beams)
        // Uses BattleTime for synchronous rotation/pulsing
        if (PROCEDURAL_SET.has(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, battleTime, layout);
            ctx.restore();
            return;
        }

        // 2. Ground Projection Logic (Ripples, Cracks, Fields)
        if (GROUND_PLANE_SET.has(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        // 3. Billboard Sprites (Smoke, Sparks, Debris, Rocks)
        if (p.type !== 'GENERIC_DEBUG') {
            BillboardPainter.draw(ctx, p, drawX, drawY, progress);
        } else {
            // 4. Critical Safe Fallback
            ctx.save();
            ctx.translate(drawX, drawY);
            ctx.fillStyle = '#ff00ff';
            ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { RenderOp, RenderOpType } from "./RenderList";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { HazardPainter } from "./grid/painters/HazardPainter";
import { SpriteManager } from "../sprites";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";
import { HexLayout } from "../../types";
import { UnitRenderSystem } from "../systems/unit";

export class RenderDispatcher {
    public static dispatch(
        ctx: CanvasRenderingContext2D, 
        op: RenderOp, 
        layout: HexLayout, 
        globalTime: number,
        unitRenderer: UnitRenderSystem
    ) {
        const snapX = Math.round(op.tx);
        const snapY = Math.round(op.ty);

        switch (op.type) {
            case RenderOpType.TERRAIN:
                TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr, globalTime, layout, op.ttheme);
                // SSOT: Height-based projection inside
                GridOverlays.drawOverlays(ctx, snapX, snapY, op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, layout);
                break;

            case RenderOpType.HAZARD: 
                // [FIX] Pass layout to HazardPainter
                if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time, layout);
                break;

            case RenderOpType.OBSTACLE:
                ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                break;

            case RenderOpType.UNIT:
                if (op.agent) unitRenderer.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                break;

            case RenderOpType.DECAL:
                ctx.save();
                ctx.translate(snapX, snapY);
                ctx.scale(op.dScale, op.dScale);
                ctx.globalAlpha = Math.min(1, op.dLife);
                ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64);
                ctx.restore();
                break;

            case RenderOpType.VFX:
                if (op.particle) {
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    // Pass globalTime (BattleTime) to renderer to sync rotations
                    ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout, globalTime);
                    ctx.restore();
                }
                break;

            case RenderOpType.PROJECTILE:
                ProjectileDrawer.draw(ctx, op, globalTime);
                break;
        }
    }
}

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine } from '../engine/game';
import { GameEvent } from '../types';
import { GameRenderer } from '../engine/renderer';

export const useGameLoop = (
    engine: GameEngine,
    canvasRef: MutableRefObject<HTMLCanvasElement | null>,
    wrapperRef: MutableRefObject<HTMLDivElement | null>,
    rendererRef: MutableRefObject<GameRenderer | null>,
    onDraw: (ctx: CanvasRenderingContext2D, fps: number) => void,
    onResize: (logicalWidth: number, logicalHeight: number) => void,
    cameraRef?: any // 新增攝像機引用傳遞
) => {
    const fpsRef = useRef(60);
    const frameRef = useRef<number>(0);
    const isMountedRef = useRef(true);
    const resizeTimerRef = useRef<number | null>(null);
    const realTimeRef = useRef(0); // Add strict monotonic real time tracking

    const drawCallbackRef = useRef(onDraw);
    const resizeCallbackRef = useRef(onResize);

    useEffect(() => {
        drawCallbackRef.current = onDraw;
        resizeCallbackRef.current = onResize;
    }, [onDraw, onResize]);

    useEffect(() => {
        isMountedRef.current = true;
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver((entries) => {
            if (!isMountedRef.current) return;

            window.requestAnimationFrame(() => {
                if (!isMountedRef.current || !canvasRef.current || !entries[0]) return;

                const { width, height } = entries[0].contentRect;
                const dpr = window.devicePixelRatio || 1;
                const logicalW = Math.floor(width);
                const logicalH = Math.floor(height);
                const physicalW = Math.floor(width * dpr);
                const physicalH = Math.floor(height * dpr);

                if (logicalW === 0 || logicalH === 0) return;

                // Sync Aspect Ratio to Engine
                engine.screenAspect = logicalW / logicalH;

                if (canvasRef.current.width !== physicalW || canvasRef.current.height !== physicalH) {
                    canvasRef.current.width = physicalW;
                    canvasRef.current.height = physicalH;
                    canvasRef.current.style.width = `${logicalW}px`;
                    canvasRef.current.style.height = `${logicalH}px`;

                    if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
                    resizeTimerRef.current = window.setTimeout(() => {
                        if (isMountedRef.current) {
                            resizeCallbackRef.current(logicalW, logicalH);
                        }
                    }, 50);
                }
            });
        });

        resizeObserver.observe(wrapperRef.current);

        return () => {
            isMountedRef.current = false;
            resizeObserver.disconnect();
            if (resizeTimerRef.current) window.clearTimeout(resizeTimerRef.current);
            cancelAnimationFrame(frameRef.current);
        };
    }, [wrapperRef, canvasRef, engine]);

    useEffect(() => {
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const loop = (t: number) => {
            if (!isMountedRef.current) return;

            if (!canvasRef.current || !rendererRef.current) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }
            const ctx = canvasRef.current.getContext('2d');
            if (!ctx) {
                frameRef.current = requestAnimationFrame(loop);
                return;
            }

            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            // Increment Real Time strictly by dt
            realTimeRef.current += dt / 1000;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 250) acc = 250; 

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            // Renderer update now handles time splitting internally using Engine state
            rendererRef.current.update(dt / 1000, engine, cameraRef);
            drawCallbackRef.current(ctx, fpsRef.current);

            frameRef.current = requestAnimationFrame(loop);
        };

        frameRef.current = requestAnimationFrame(loop);

        return () => {
            cancelAnimationFrame(frameRef.current);
        };
    }, [engine, canvasRef, rendererRef, cameraRef]);

    return { fpsRef };
};

import { Agent, GameEngine } from "./game";
import { Hex, GameEvent, Skill } from "../types";
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";
import { RenderPipeline } from "./renderers/RenderPipeline";
import { StatusOrchestrator } from "./renderers/status/StatusOrchestrator"; 
import { SequenceSystem } from "./systems/visuals/SequenceSystem"; 

export { Camera };

export class GameRenderer {
    public grid: GridSystem = new GridSystem();
    public vfx: VFXSystem = new VFXSystem();
    public vfxRenderer: VFXRenderer = new VFXRenderer();
    public unit: UnitRenderSystem = new UnitRenderSystem();
    public statusOrchestrator: StatusOrchestrator = new StatusOrchestrator(); 
    public hud: HUDSystem = new HUDSystem();
    public camera: CameraSystem = new CameraSystem();
    private eventListener: VisualEventListener = new VisualEventListener();
    private pipeline: RenderPipeline = new RenderPipeline(this);

    private boundEngine: GameEngine | null = null;

    // Decoupling: Explicit binding allows us to subscribe to events
    public bind(engine: GameEngine) {
        if (this.boundEngine === engine) return;

        // Unbind previous if exists
        if (this.boundEngine) {
            this.boundEngine.bus.off('GAME_RESET', this.handleReset);
            this.boundEngine.bus.off('GAME_CLEAR', this.handleReset);
            this.boundEngine.bus.off('ENV_UPDATE', this.handleReset);
            this.boundEngine.bus.off('CAMERA_SHAKE', this.handleShake);
            this.boundEngine.bus.off('CAMERA_MOVE', this.handleCameraMove);
        }

        this.boundEngine = engine;

        // Bind new
        this.boundEngine.bus.on('GAME_RESET', this.handleReset);
        this.boundEngine.bus.on('GAME_CLEAR', this.handleReset);
        this.boundEngine.bus.on('ENV_UPDATE', this.handleReset);
        this.boundEngine.bus.on('CAMERA_SHAKE', this.handleShake);
        this.boundEngine.bus.on('CAMERA_MOVE', this.handleCameraMove);
    }

    private handleReset = () => {
        this.reset();
    }

    private handleShake = (data: { intensity: number }) => {
        this.camera.addTrauma(data.intensity);
    }

    private handleCameraMove = (data: { x: number, y: number, zoom: number }) => {
        this.camera.setDirectorTarget(data.x, data.y, data.zoom);
    }

    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
        this.grid.reset(); 
    }

    public setTransitionPhase(phase: 'IN' | 'OUT' | 'IDLE') { 
        this.pipeline.setTransitionPhase(phase); 
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number { return this.grid.getTerrainHeight(q, r, engine); }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2, cy = height / 2;
        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;
        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    public update(dt: number, engine: GameEngine, externalCameraRef?: any): void {
        // 1. Camera Update (Always RealTime for smoothness)
        this.camera.update(dt);

        if (externalCameraRef?.current) {
            externalCameraRef.current.x = this.camera.x;
            externalCameraRef.current.y = this.camera.y;
        }

        // 2. SSOT Time Calculation
        // Simulation Time Delta = Real DT * TimeScale (0 if paused)
        const simDt = engine.isRunning ? dt * engine.timeScale : 0;
        const battleTime = engine.battleTime; // SSOT from Logic

        // 3. Sequence System (Logic Driven)
        SequenceSystem.update(engine, this.vfx);

        // 4. Render Pipeline (Transitions)
        this.pipeline.update(dt, engine); 

        // 5. VFX System (Time Dilation Applied)
        // Ambience and Particles now move in sync with game speed (Bullet Time ready)
        this.vfx.update(
            simDt, 
            battleTime, 
            engine.currentScene.ambientType, 
            (x, y) => this.grid.getTerrainHeight(
                this.grid.getHexAtWorldPoint(x, y, engine)?.q || 0,
                this.grid.getHexAtWorldPoint(x, y, engine)?.r || 0,
                engine
            )
        );

        // 6. HUD System (Always RealTime, UI should not freeze)
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void { this.eventListener.process(events, engine, this.vfx, this.hud, this.grid, this.camera); }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, battleTime: number, realTime: number): void {
        this.pipeline.draw(ctx, engine, camera, highlight, fps, hoveredHex, hoveredSkill, battleTime, realTime);
    }
}

import { Agent } from "../game";
import { Particle } from "../systems/vfx/state";
import { Projectile, Point, GroundHazard } from "../../types";

export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL,
    HAZARD
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    sortKey: number = 0;
    y: number = 0; 
    z: number = 0; 
    tx: number = 0; ty: number = 0; th: number = 0; 
    tsize: number = 0; ttheme: any = null;
    tq: number = 0; tr: number = 0;
    ttype: string = ''; tdetail: string = '';
    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined;
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;
    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;
    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;
    pVisX: number = 0; pVisY: number = 0; pVisShadowY: number = 0;
    pSkillVis: string = ''; pColor: string = '';
    pIsUlt: boolean = false; pAngle: number = 0; pSpin: number = 0;
    pScale: number = 1.0; 
    pTrail: Point[] = []; 
    proj: Projectile | null = null;
    dColor: string = ''; dScale: number = 1; dLife: number = 0;
    time: number = 0;

    public clear() {
        this.type = RenderOpType.TERRAIN;
        this.sortKey = 0;
        this.y = 0; this.z = 0;
        this.tx = 0; this.ty = 0; this.th = 0;
        this.tq = 0; this.tr = 0;
        this.agent = null;
        this.particle = null;
        this.proj = null;
        this.pIsUlt = false; 
        this.pScale = 1.0;
        this.oRange = false;
        this.oHover = false;
        this.oStatus = undefined;
        this.oHazard = undefined;
        this.oDanger = undefined;
        this.uSelected = false;
        this.uSilhouette = false;
        this.vChaos = false;
        this.ttheme = null;
        this.pTrail = [];
    }
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;
    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        const op = this.ops[this.count++];
        op.clear(); 
        return op;
    }

    public sort() {
        if (this.count <= 1) return;
        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];

            /**
             * 唯一數學排序規範 v17.1 (Topological Ground Sort - Z Fix)
             * 
             * 1. 地形層 (Terrain): 使用 Visual Base Y (ty) 排序。
             * 2. 物件層 (Unit/Prop): 使用 Footprint Y (y) 排序。
             *    [CRITICAL] 不將 Z 軸高度計入排序鍵值。
             *    在 2.5D 投影中，深度完全由 Y 軸決定。將 Z 計入會導致跳躍單位錯誤地覆蓋前方單位。
             */

            let sortKey = 0;

            if (op.type === RenderOpType.TERRAIN) {
                // 地形層：基礎權重 0 ~ 20,000,000
                sortKey = Math.floor((op.ty + 5000) * 100);
            } 
            else {
                // 物件層：基礎權重 20,000,000 +
                let layerBase = 0;
                if (op.type === RenderOpType.HAZARD || op.type === RenderOpType.DECAL) layerBase = 20000000;
                else if (op.type === RenderOpType.OBSTACLE || op.type === RenderOpType.UNIT) layerBase = 40000000;
                else if (op.type === RenderOpType.VFX || op.type === RenderOpType.PROJECTILE) layerBase = 60000000;

                // 同層內依 Screen Y 排序 (由後至前 -> Y 值由小到大)
                // 只使用 op.y (Footprint)，忽略 op.z (Altitude)
                sortKey = layerBase + Math.floor(op.y * 100);
            }

            // 特殊：奧義/高空特效絕對置頂
            if (op.pIsUlt || op.z > 600) sortKey += 100000000;

            op.sortKey = sortKey;
            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { GameEngine } from "../game";
import { GroundHazard, Team, MovementType } from "../../types";
import { HexUtils } from "../utils";
import { HAZARD_VISUALS } from "../../data/vfx/hazard_visuals";
import { COMBAT_PARAM } from "../../constants";

export class HazardSystem {
    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number,
        engine: GameEngine 
    ) {
        if (!engine.map.isValid(q, r)) return;
        const key = HexUtils.key({q, r});
        const hazards = engine.state.hazards;
        const existing = hazards.get(key);

        if (existing) {
            if (existing.type === type && existing.team === team) {
                existing.duration = Math.max(existing.duration, duration);
                existing.power = Math.max(existing.power, power); 
                existing.sourceId = sourceId; 
                return;
            }
        }

        const hazard: GroundHazard = {
            id: engine.nextId('HZD'),
            q, r, type, duration, sourceId, team, color, power, interval, timer: 0 
        };

        hazards.set(key, hazard);

        const def = HAZARD_VISUALS[type];
        if (def && def.spawnVfx) {
            const px = HexUtils.toPx(q, r, engine.mapConfig);
            engine.events.push({ 
                type: 'HAZARD_SPAWN', 
                pos: { x: px.x, y: px.y }, 
                text: def.spawnVfx 
            });
        }
    }

    public update(dt: number, engine: GameEngine) {
        const hazards = engine.state.hazards;
        const toRemove: string[] = [];

        for (const [key, h] of hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt; 
            if (h.duration <= 0) toRemove.push(key);
        }
        toRemove.forEach(k => hazards.delete(k));

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished) return;

            const hazard = hazards.get(HexUtils.key({q: agent.q, r: agent.r}));
            if (!hazard) return;

            if (hazard.team !== agent.team) {
                // Flying units are immune to ground hazards like Fire/Poison
                if (agent.movementType === MovementType.FLYING && (hazard.type === 'FIRE' || hazard.type === 'POISON')) return;

                if (hazard.timer <= 0) {
                    const dmg = hazard.power;
                    agent.hp = Math.max(0, agent.hp - dmg);
                    engine.events.push({ 
                        type: 'DAMAGE', 
                        pos: {x: agent.px, y: agent.py}, 
                        value: -Math.floor(dmg), 
                        color: hazard.color,
                        skill: { color: hazard.color, ccType: 'DOT' } as any 
                    });
                    agent.hitFlashTimer = COMBAT_PARAM.HIT_FLASH_DURATION;
                }

                if (hazard.type === 'GRAVITY') {
                    const center = HexUtils.toPx(hazard.q, hazard.r, engine.mapConfig);
                    const dx = center.x - agent.px, dy = center.y - agent.py;
                    const dist = Math.sqrt(dx*dx + dy*dy);
                    if (dist > COMBAT_PARAM.GRAVITY_MIN_DIST) {
                        agent.physics.vx += (dx/dist) * COMBAT_PARAM.GRAVITY_PULL_FORCE * dt;
                        agent.physics.vy += (dy/dist) * COMBAT_PARAM.GRAVITY_PULL_FORCE * dt;
                        agent.moveSpeedMult = COMBAT_PARAM.GRAVITY_SPEED_REDUCTION; 
                    }
                } else if (hazard.type === 'ICE') {
                    agent.moveSpeedMult = COMBAT_PARAM.ICE_SPEED_REDUCTION;
                }
            }
        });

        for (const h of hazards.values()) {
            if (h.timer <= 0) h.timer = h.interval;
        }
    }
}

import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { MovementType, GroundHazard } from "../../types";
import { MapGenerator } from "./map/MapGenerator";
import { MapSpatial } from "./map/MapSpatial";
export class MapSystem {
    public agentMap: Map<number, Agent> = new Map();
    public mapKeys: Set<string> = new Set();
    private validHashes: Set<number> = new Set();
    public obstacles: Map<string, string> = new Map();
    public obstaclesHash: Set<number> = new Set();
    public heightMap: Map<string, number> = new Map();
    constructor() {}
    public registerAgent(agent: Agent) {
        const hash = HexUtils.hash(agent.q, agent.r);
        this.agentMap.set(hash, agent);
    }
    public unregisterAgent(agent: Agent) {
        const hash = HexUtils.hash(agent.q, agent.r);
        if (this.agentMap.get(hash) === agent) {
            this.agentMap.delete(hash);
        }
    }
    public removeAgentAt(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        this.agentMap.delete(hash);
    }
    public getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }
    public updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        const oldH = this.getTerrainHeight(agent.q, agent.r);
        const newH = this.getTerrainHeight(newQ, newR);
        const deltaH = oldH - newH;
        agent.physics.z += deltaH;
        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }
    public clearAgents() {
        this.agentMap.clear();
    }
    public getTerrainHeight(q: number, r: number): number { return this.heightMap.get(HexUtils.key({q, r})) || 0; }
    public getHeightByKey(key: string): number { return this.heightMap.get(key) || 0; }
    public getMapKeys(): Set<string> { return this.mapKeys; }
    public isValid(q: number, r: number) { return this.validHashes.has(HexUtils.hash(q, r)); }
    public isValidHash(h: number) { return this.validHashes.has(h); }
    public resetData() {
        this.mapKeys.clear();
        this.validHashes.clear();
        this.obstacles.clear();
        this.obstaclesHash.clear();
        this.heightMap.clear();
    }
    public registerTile(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.mapKeys.add(k);
        this.validHashes.add(h);
    }
    public removeTile(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.validHashes.delete(h);
        this.mapKeys.delete(k);
        this.heightMap.delete(k);
        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }
    public setHeight(key: string, height: number) { this.heightMap.set(key, height); }
    public setObstacle(q: number, r: number, type: string) {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.set(k, type);
        this.obstaclesHash.add(h);
    }
    public removeObstacle(q: number, r: number) {
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        this.obstacles.delete(k);
        this.obstaclesHash.delete(h);
    }
    public toggleObstacle(q: number, r: number, engine: GameEngine, type: string = 'WALL') {
        if (!this.isValid(q, r)) return;
        const k = HexUtils.key({q, r});
        const h = HexUtils.hash(q, r);
        if (this.obstaclesHash.has(h)) {
            this.obstacles.delete(k);
            this.obstaclesHash.delete(h);
        } else {
            if (!this.getAgentAt(q, r)) {
                this.obstacles.set(k, type);
                this.obstaclesHash.add(h);
            }
        }
    }
    public randomizeEnvironment(engine: GameEngine) { MapGenerator.randomize(this, engine); }
    public rebuildMap(engine: GameEngine) { MapGenerator.rebuild(this, engine); }
    public isBlocked(q: number, r: number, engine: GameEngine, ignoreId: string | null = null, movementType: MovementType = MovementType.GROUND): boolean {
        return MapSpatial.isBlocked(this, q, r, engine, ignoreId, movementType);
    }
    public hasObstacle(q: number, r: number): boolean {
        return MapSpatial.hasObstacle(this, q, r);
    }
    public hasObstacleHash(h: number): boolean {
        return this.obstaclesHash.has(h);
    }
    public getHazardAt(q: number, r: number, engine: GameEngine): GroundHazard | undefined {
        return engine.hazards.get(HexUtils.key({ q, r }));
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useCameraControl } from '../hooks/useCameraControl';
import { Icons } from './ui/icons';
interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void;
}
const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const rendererRef = useRef<GameRenderer | null>(null);

    // Lazy init renderer
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        rendererRef.current.bind(engine);
        engine.renderer = rendererRef.current;
    }

    const { camera, centerCamera, zoom } = useGameCamera(engine);
    useCameraControl({
        canvasRef, 
        cameraRef: camera,
        onZoom: zoom,
        engine 
    });

    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    });

    // Update transition state in renderer (Logic moved out of View)
    useEffect(() => {
        if (rendererRef.current) {
            rendererRef.current.setTransitionPhase(transitionPhase);
        }
    }, [transitionPhase]);

    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        const realTime = performance.now() / 1000;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill,
            engine.battleTime,
            realTime
        );

        // Editor Drag Overlay
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;
            ctx.save();
            ctx.scale(dpr, dpr);
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;
            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); 
            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;
            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize,
        camera
    );

    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
