import { Agent, GameEngine } from "../game";
import { PhysicsEngine } from "../physics/PhysicsEngine";
import { MovementType } from "../../types";

export class PhysicsSystem {
    private engine: PhysicsEngine;

    constructor() {
        this.engine = new PhysicsEngine();
    }

    public update(dt: number, engine: GameEngine) {
        // Physics integration only. Visual side-effects (dust, sparks) 
        // are now handled by the AgentVFXSystem in the render loop.
        for (const a of engine.agents) {
            this.engine.update(a, dt, engine);
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { HexUtils } from "../../utils";

export class ControlSystem {

    public update(agent: Agent, dt: number, engine: GameEngine) {
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // Diminishing Returns (DR) decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // Timer Decrements
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // State Logic: Banishment
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            // Visuals handled by AgentVFXSystem
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        // State Logic: Stun
        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        // State Logic: Fear (Random Movement)
        if (agent.fearTimer > 0) {
            if (agent.rootTimer <= 0) {
                if (!agent.isMoving && agent.aiUpdateTimer <= 0) {
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        const result = engine.moveAgentToHex(agent, targetHex, 0, 1.5);
                        agent.aiUpdateTimer = (result === 'R') ? 0.5 : 0.8;
                    } else {
                        agent.aiUpdateTimer = 0.8; 
                    }
                }
            } else {
                agent.isMoving = false;
                agent.path = [];
            }
        }

        // State Logic: Root
        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }
    }
}

import { GameEngine, Agent } from "../../game";
import { VFXSystem } from "../vfx";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { MovementType } from "../../../types";

/**
 * 視覺狀態觀察者 (Visual State Observer)
 * 負責監控 Agent 的狀態（速度、Debuff）並生成對應的持續性粒子。
 * 這屬於 Render Loop 的一部分，確保 Logic Loop 純淨無汙染。
 */
export class AgentVFXSystem {
    private vfxTimers = new Map<string, number>();
    private dustTimer: number = 0;

    public update(dt: number, engine: GameEngine, vfx: VFXSystem) {
        // 1. Friction Dust / Sparks Logic
        this.dustTimer += dt;
        const canSpawnDust = this.dustTimer > 0.05; // Limit rate (20fps)

        if (canSpawnDust) {
            for (const a of engine.agents) {
                if (a.hp <= 0) continue;

                const speedSq = a.physics.vx*a.physics.vx + a.physics.vy*a.physics.vy;
                const isGrounded = a.physics.z < 5;
                const isFlyingUnit = a.movementType === MovementType.FLYING;

                // Threshold: 300px/s
                if (speedSq > 90000 && isGrounded && !isFlyingUnit) {
                    const type = speedSq > 250000 ? 'SPARK' : 'DUST';
                    const effectId = type === 'SPARK' ? 'FX_STATUS_STUN_LOOP' : 'FX_STATUS_ROOT_LOOP';
                    const terrainH = engine.map.getTerrainHeight(a.q, a.r);

                    vfx.playEffect(effectId, a.px + a.physics.x, a.py + a.physics.y, terrainH + 5);
                }
            }
            this.dustTimer = 0;
        }

        // 2. Status Effect Particles (Poison bubbles, Stun stars, etc.)
        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;
            this.processStatusVFX(a, dt, engine, vfx);
        }
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine, vfx: VFXSystem) {
        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                const pz = agent.physics.z + 45; // Chest height

                vfx.playEffect(
                    def.particleEffect, 
                    agent.px + agent.physics.x, 
                    agent.py + agent.physics.y, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('BURN', agent.dotTimer > 0 && agent.dotDmg > 0); // Assuming mapped elsewhere or generic
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";
import { AgentVFXSystem } from "./vfx/AgentVFXSystem";
import { Point3D } from "../math/VisualMath";
import { GameEngine } from "../game";

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();
    private agentVFX: AgentVFXSystem = new AgentVFXSystem();

    public reset() { this.state.reset(); }

    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }

    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x; p.ty = end.y; p.tz = end.z;
        p.x = start.x; p.y = start.y; p.z = start.z;
        p.life = duration; p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; p.style = styleId; p.locked = true;
        this.state.particles.push(p);
    }

    /**
     * SSOT Update:
     * @param dt - Scaled Simulation Delta Time (0 if paused)
     * @param battleTime - Current Battle Time (for procedural shaders)
     * @param engine - Reference to game engine for reading Agent state
     */
    update(
        dt: number, 
        battleTime: number, 
        ambientType: string, 
        getTerrainHeight: (x: number, y: number) => number,
        engine?: GameEngine 
    ) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            // Apply Time Dilation to Delays
            if (p.delay && p.delay > 0) { 
                p.delay -= dt; 
                continue; 
            }

            p.life -= dt;

            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop(); count--; continue;
            }

            if (p.locked) { 
                p.rotation += p.vRotation * dt; 
                continue; 
            }

            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX, dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) p.life = 0; 
            }

            VFXPhysics.update(p, dt, getTerrainHeight);
        }

        // Decals also respect time scale
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }

        this.ambience.update(dt, ambientType, this.state);

        // Update Agent-based Continuous VFX (Dust, Status)
        // Only if engine is provided (it is provided by GameRenderer)
        if (engine) {
            this.agentVFX.update(dt, engine, this);
        }
    }
}

import { Agent, GameEngine } from "./game";
import { Hex, GameEvent, Skill } from "../types";
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";
import { RenderPipeline } from "./renderers/RenderPipeline";
import { StatusOrchestrator } from "./renderers/status/StatusOrchestrator"; 
import { SequenceSystem } from "./systems/visuals/SequenceSystem"; 

export { Camera };

export class GameRenderer {
    public grid: GridSystem = new GridSystem();
    public vfx: VFXSystem = new VFXSystem();
    public vfxRenderer: VFXRenderer = new VFXRenderer();
    public unit: UnitRenderSystem = new UnitRenderSystem();
    public statusOrchestrator: StatusOrchestrator = new StatusOrchestrator(); 
    public hud: HUDSystem = new HUDSystem();
    public camera: CameraSystem = new CameraSystem();
    private eventListener: VisualEventListener = new VisualEventListener();
    private pipeline: RenderPipeline = new RenderPipeline(this);

    private boundEngine: GameEngine | null = null;

    // Decoupling: Explicit binding allows us to subscribe to events
    public bind(engine: GameEngine) {
        if (this.boundEngine === engine) return;

        // Unbind previous if exists
        if (this.boundEngine) {
            this.boundEngine.bus.off('GAME_RESET', this.handleReset);
            this.boundEngine.bus.off('GAME_CLEAR', this.handleReset);
            this.boundEngine.bus.off('ENV_UPDATE', this.handleReset);
            this.boundEngine.bus.off('CAMERA_SHAKE', this.handleShake);
            this.boundEngine.bus.off('CAMERA_MOVE', this.handleCameraMove);
        }

        this.boundEngine = engine;

        // Bind new
        this.boundEngine.bus.on('GAME_RESET', this.handleReset);
        this.boundEngine.bus.on('GAME_CLEAR', this.handleReset);
        this.boundEngine.bus.on('ENV_UPDATE', this.handleReset);
        this.boundEngine.bus.on('CAMERA_SHAKE', this.handleShake);
        this.boundEngine.bus.on('CAMERA_MOVE', this.handleCameraMove);
    }

    private handleReset = () => {
        this.reset();
    }

    private handleShake = (data: { intensity: number }) => {
        this.camera.addTrauma(data.intensity);
    }

    private handleCameraMove = (data: { x: number, y: number, zoom: number }) => {
        this.camera.setDirectorTarget(data.x, data.y, data.zoom);
    }

    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
        this.grid.reset(); 
    }

    public setTransitionPhase(phase: 'IN' | 'OUT' | 'IDLE') { 
        this.pipeline.setTransitionPhase(phase); 
    }

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number { return this.grid.getTerrainHeight(q, r, engine); }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2, cy = height / 2;
        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;
        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    public update(dt: number, engine: GameEngine, externalCameraRef?: any): void {
        // 1. Camera Update (Always RealTime for smoothness)
        this.camera.update(dt);

        if (externalCameraRef?.current) {
            externalCameraRef.current.x = this.camera.x;
            externalCameraRef.current.y = this.camera.y;
        }

        // 2. SSOT Time Calculation
        // Simulation Time Delta = Real DT * TimeScale (0 if paused)
        const simDt = engine.isRunning ? dt * engine.timeScale : 0;
        const battleTime = engine.battleTime; // SSOT from Logic

        // 3. Sequence System (Logic Driven)
        SequenceSystem.update(engine, this.vfx);

        // 4. Render Pipeline (Transitions)
        this.pipeline.update(dt, engine); 

        // 5. VFX System (Time Dilation Applied)
        // Ambience and Particles now move in sync with game speed (Bullet Time ready)
        // NEW: Pass 'engine' so VFXSystem can read Agent states for dust/status effects
        this.vfx.update(
            simDt, 
            battleTime, 
            engine.currentScene.ambientType, 
            (x, y) => this.grid.getTerrainHeight(
                this.grid.getHexAtWorldPoint(x, y, engine)?.q || 0,
                this.grid.getHexAtWorldPoint(x, y, engine)?.r || 0,
                engine
            ),
            engine 
        );

        // 6. HUD System (Always RealTime, UI should not freeze)
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void { this.eventListener.process(events, engine, this.vfx, this.hud, this.grid, this.camera); }

    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, battleTime: number, realTime: number): void {
        this.pipeline.draw(ctx, engine, camera, highlight, fps, hoveredHex, hoveredSkill, battleTime, realTime);
    }
}

import { Point } from "../../types";
import { Point3D } from "./VisualMath";

export { Point3D };

/**
 * 飛行幾何真理庫 v14.1 - Analytic Ballistics (Fixed Angle Logic)
 */
export const TrajectoryMath = {

    /**
     * 線性插值座標 (解析解)
     */
    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    /**
     * 解析拋物線 (Parabolic Arc)
     * 計算在進度 t 時的 3D 座標，h 為頂點拱高
     */
    parabolic: (start: Point3D, end: Point3D, t: number, h: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;
        const linearZ = start.z * (1 - t) + end.z * t;
        // 拋物線高度公式: 4h * t * (1-t)
        const arcZ = 4 * h * t * (1 - t);
        return { x, y, z: linearZ + arcZ };
    },

    /**
     * 螺旋擺動軌跡 (Wobble Path)
     */
    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 1) return base;

        // 計算垂直於運動方向的法線向量
        const nx = -dy / dist;
        const ny = dx / dist;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z + Math.cos(t * Math.PI * 2 * freq) * amp * 0.5
        };
    },

    /**
     * 計算解析解在一階導數下的切向角
     * 會考慮 Z 軸變化對等角投影 (Y 軸壓縮) 的視覺影響
     * @param yScale - 如果輸入座標已經是視覺座標 (Projected)，請傳 1.0。如果是邏輯座標，傳 ISO_SCALE_Y。
     */
    getProjectedAngle: (func: (t: number) => Point3D, t: number, yScale: number = 1.0): number => {
        const dt = 0.01;
        let t1 = t;
        let t2 = t + dt;

        // 邊界處理：如果在終點，向後採樣以保持角度
        if (t2 > 1.0) {
            t2 = t;
            t1 = t - dt;
        }
        // 邊界處理：如果在起點，確保 t1 >= 0
        if (t1 < 0) t1 = 0;

        const p1 = func(t1);
        const p2 = func(t2);

        const dx = p2.x - p1.x;
        const dy = p2.y - p1.y;
        const dz = p2.z - p1.z;

        // 視覺 Y 變化量 = (物理 Y * Y縮放) - 高度變化 Z
        // 注意：在我們目前的架構中，p.y 通常已經是 Screen Space Ground Y，所以 yScale 應設為 1.0
        const vy = dy * yScale - dz;

        return Math.atan2(vy, dx);
    }
};

import { GameEngine } from "../../../game";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath, Point3D } from "../../../math/VisualMath";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const traj = p.trajectoryInfo;

            // 1. Use Logic Position (SSOT)
            // No more TrajectoryMath.calculate here. Logic has already done it.
            const current3D = { x: p.x, y: p.y, z: p.z };

            // 2. Calculate Visual Angle (Derivative)
            // We still need the formula to calculate the angle tangent based on trajectory function
            const getPosAt = (t: number) => {
                const start: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
                const end: Point3D = { x: p.endX, y: p.endY, z: p.endZ };
                if (traj.type === 'ARC') return TrajectoryMath.parabolic(start, end, t, traj.arcHeight || 150);
                if (traj.type === 'WOBBLE') return TrajectoryMath.wobble(start, end, t, traj.wobbleAmp || 15, traj.wobbleFreq || 2);
                return TrajectoryMath.linear(start, end, t);
            };

            // FIX: Pass 1.0 as yScale because p.startY/endY are already Screen Coordinates (Projected)
            const visAngle = TrajectoryMath.getProjectedAngle(getPosAt, p.t, 1.0);

            // 3. Project to Screen
            const transOffset = VisualMath.getTransitionOffset(current3D.x, current3D.y, engine.mapConfig, transitionT, transitionPhase);
            // Z subtraction converts 3D world pos to 2D screen pos (y - z)
            const visY = VisualMath.getIsoVisualY(current3D.y, current3D.z) + transOffset;

            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = current3D.y; 
            op.z = 5000 + current3D.z; 

            op.pVisX = current3D.x;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = traj.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = traj.spinSpeed ? (p.t * p.totalDuration * traj.spinSpeed) : 0;
            op.pScale = traj.scale || 1.0; 

            // 4. Trails (Calculated purely visually backwards from SSOT position)
            op.pTrail = [];
            // Use visuals DB or default for trail length, as it's purely cosmetic and not in SSOT Logic state
            const trailSamples = p.skill.tag === 'ULT' ? 20 : 10;

            if (trailSamples > 0) {
                const step = 0.015; 
                for (let j = 1; j <= trailSamples; j++) {
                    const tPast = Math.max(0, p.t - j * step);
                    // We must recalculate past positions as we don't store history in Logic
                    const past3D = getPosAt(tPast);
                    const pOffset = VisualMath.getTransitionOffset(past3D.x, past3D.y, engine.mapConfig, transitionT, transitionPhase);
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + pOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { Point } from "../../types";
import { Point3D } from "./VisualMath";

export { Point3D };

export interface TrajectoryConfig {
    type: 'LINEAR' | 'ARC' | 'WOBBLE' | 'INSTANT';
    arcHeight?: number;
    wobbleFreq?: number;
    wobbleAmp?: number;
}

/**
 * 飛行幾何真理庫 v15.0 - Pure 3D Trajectory Logic
 * 只負責計算 3D 空間中的點，不處理視覺投影。
 */
export const TrajectoryMath = {

    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    parabolic: (start: Point3D, end: Point3D, t: number, h: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;
        const linearZ = start.z * (1 - t) + end.z * t;
        const arcZ = 4 * h * t * (1 - t);
        return { x, y, z: linearZ + arcZ };
    },

    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 1) return base;

        const nx = -dy / dist;
        const ny = dx / dist;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z + Math.cos(t * Math.PI * 2 * freq) * amp * 0.5
        };
    },

    /**
     * SSOT 軌跡計算入口
     */
    evaluate: (config: TrajectoryConfig, start: Point3D, end: Point3D, t: number): Point3D => {
        if (config.type === 'ARC') {
            return TrajectoryMath.parabolic(start, end, t, config.arcHeight || 150);
        }
        if (config.type === 'WOBBLE') {
            return TrajectoryMath.wobble(start, end, t, config.wobbleAmp || 15, config.wobbleFreq || 2);
        }
        return TrajectoryMath.linear(start, end, t);
    }
};

import { Agent, GameEngine } from "../game";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    /**
     * 計算兩個 3D 點在 2D 投影平面上的視覺角度
     * SSOT: 使用 getIsoVisualY 公式進行投影，確保角度與視覺一致
     */
    public static calculateProjectedAngle(p1: Point3D, p2: Point3D): number {
        const dx = p2.x - p1.x;
        // 視覺 Y 差值 = (y2 - z2) - (y1 - z1)
        const vy1 = this.getIsoVisualY(p1.y, p1.z);
        const vy2 = this.getIsoVisualY(p2.y, p2.z);
        const dy = vy2 - vy1;
        return Math.atan2(dy, dx);
    }

    /**
     * 套用渲染層級偏置以解決 Z-fighting
     */
    public static applyLayerBias(surfaceY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return surfaceY - this.Z_LAYERS[layer];
    }

    /**
     * 計算實體（如 HUD）的視覺 Y 軸錨點
     */
    public static getEntityVisualY(py: number, terrainH: number, physicsY: number, physicsZ: number, offset: number): number {
        return (py + physicsY) - terrainH - physicsZ + offset;
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    /**
     * 計算頭頂特效（如狀態圖標）的視覺 Y 軸位置
     */
    public static getOverheadVisualY(surfaceY: number, z: number, bob: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET - VISUAL_ANCHORS.HEAD_OFFSET + bob;
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            const q = parseInt(parts[0]);
            const r = parseInt(parts[1]);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            return { x: p.x, y: p.y, z: h + 2 };
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill, Team } from "../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE } from "../../../data/vfx/projectile_visuals";
import { TrajectoryMath, Point3D } from "../../math/TrajectoryMath";
import { VisualMath } from "../../math/VisualMath";
import { SkillExecutor } from "./SkillExecutor";
import { HazardManager } from "./HazardManager";
import { HEX_SIZE } from "../../../constants";

export class ProjectileSystem {
    private pool: Projectile[] = [];

    constructor() {
        for (let i = 0; i < 60; i++) this.pool.push(this.createEmptyProjectile());
    }

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        const list = engine.projectiles;
        for (let i = list.length - 1; i >= 0; i--) {
            const p = list[i];
            if (!p.active) { this.removeProjectile(i, engine); continue; }

            // 1. Advance Time
            const dtStep = dt / p.totalDuration;
            p.t = Math.min(1.0, p.t + dtStep);

            // 2. Calculate True 3D Position (SSOT)
            // Logic now uses the centralized math function
            this.updatePosition(p);

            // 3. Impact Check
            if (p.t >= 1.0) {
                this.handleImpact(p, engine, skillExecutor);
                this.release(p);
                this.removeProjectile(i, engine);
            }
        }
    }

    private updatePosition(p: Projectile) {
        const start: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
        const end: Point3D = { x: p.endX, y: p.endY, z: p.endZ };

        // Use SSOT evaluate function
        const pos = TrajectoryMath.evaluate(p.trajectoryInfo, start, end, p.t);

        p.x = pos.x;
        p.y = pos.y;
        p.z = pos.z;
    }

    private handleImpact(p: Projectile, engine: GameEngine, skillExecutor: SkillExecutor) {
        const source = engine.agents.find(a => a.id === p.sourceId);
        const hitPos = { x: p.endX, y: p.endY };

        if (p.skill.type === 'AOE') {
            const radiusGrid = p.skill.aoeRadius || 1;
            const radiusPx = radiusGrid * HEX_SIZE + 10;
            const radiusSq = radiusPx * radiusPx;

            engine.agents.forEach(t => {
                if (t.team !== p.team && t.hp > 0 && !t.banished) {
                    const targetPx = VisualMath.getUnitAnchor(t, engine);
                    const dx = targetPx.x - hitPos.x;
                    const dy = targetPx.y - hitPos.y;
                    const distSq = dx*dx + dy*dy;

                    if (distSq <= radiusSq) {
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine);
                    }
                }
            });

            engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
        } else {
            const target = engine.agents.find(a => a.id === p.targetId);
            if (target && target.hp > 0 && !target.banished) {
                if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
            }
        }
        engine.events.push({ type: 'PROJECTILE_HIT', pos: hitPos, skill: p.skill });
    }

    private removeProjectile(idx: number, engine: GameEngine) {
        const last = engine.projectiles.pop();
        if (last && idx < engine.projectiles.length) engine.projectiles[idx] = last;
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        const target = skill.type === 'AOE' ? (source.targetHex || source.target) : source.target;
        if (!target) return;

        const targetId = (target as any).id || `ground-${(target as any).q},${(target as any).r}`;
        const launchPoint = VisualMath.getUnitAnchor(source, engine);
        const targetPoint = VisualMath.resolveTargetPoint(targetId, engine);

        const dx = targetPoint.x - launchPoint.x;
        const dy = targetPoint.y - launchPoint.y;
        const totalDist = Math.sqrt(dx*dx + dy*dy);
        const speed = skill.projectileSpeed || 800;

        const p = this.pool.pop() || this.createEmptyProjectile();
        p.active = true;
        p.id = engine.nextId('PRJ');
        p.sourceId = source.id;
        p.team = source.team;
        p.skill = skill;
        p.t = 0;
        p.totalDuration = Math.max(0.1, totalDist / speed);
        p.startX = launchPoint.x; p.startY = launchPoint.y; p.startZ = launchPoint.z;
        p.endX = targetPoint.x; p.endY = targetPoint.y; p.endZ = targetPoint.z;
        p.totalDist = totalDist;
        p.targetId = targetId;
        p.trail = [];

        const visualKey = skill.visualProjectileEffect || skill.visual || 'BOLT';
        const def = PROJECTILE_VISUALS[visualKey] || DEFAULT_PROJECTILE;

        p.trajectoryInfo = {
            type: def.trajectory,
            arcHeight: def.arcHeight,
            wobbleFreq: def.wobbleFreq,
            wobbleAmp: def.wobbleAmp,
            spinSpeed: def.spinSpeed,
            spriteKey: def.spriteKey || visualKey,
            scale: def.scale
        };

        this.updatePosition(p);

        engine.projectiles.push(p);
        engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill, targetId });
    }

    private release(p: Projectile) { p.active = false; p.trail = []; this.pool.push(p); }

    private createEmptyProjectile(): Projectile {
        return { 
            id: '', active: false, createdAt: 0, lifespan: 0, 
            x: 0, y: 0, z: 0, t: 0, totalDuration: 0,
            startX: 0, startY: 0, startZ: 0, endX: 0, endY: 0, endZ: 0, totalDist: 0,
            targetId: '', targetPos: {x: 0, y: 0}, 
            speed: 0, skill: {} as Skill, sourceId: '', team: Team.BLUE, trail: [],
            trajectoryInfo: { type: 'LINEAR' }
        };
    }
}

import { GameEngine } from "../../../game";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath, Point3D } from "../../../math/VisualMath";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        for (const p of engine.projectiles) {
            if (!p.active) continue;

            const traj = p.trajectoryInfo;
            const start: Point3D = { x: p.startX, y: p.startY, z: p.startZ };
            const end: Point3D = { x: p.endX, y: p.endY, z: p.endZ };

            // 1. Get Logic Position (Already calculated by ProjectileSystem)
            const current3D = { x: p.x, y: p.y, z: p.z };

            // 2. Calculate Visual Angle (Derivative)
            // Use TrajectoryMath to predict slightly future position
            // Then use VisualMath to project both points and get the 2D angle

            // Sample a bit ahead to get the tangent
            let tNext = p.t + 0.01;
            // Handle end-of-flight boundary (use backward diff if at end)
            if (tNext > 1.0) tNext = p.t - 0.01; 

            const next3D = TrajectoryMath.evaluate(traj, start, end, tNext);

            // If at end, vector is p -> prev, so angle needs flip? 
            // calculateProjectedAngle(p1, p2) gives angle from p1 to p2.
            // If p.t < 1.0, we want angle(current, next).
            // If p.t >= 1.0, we used backward diff (next is actually prev), so we want angle(prev, current).

            let visAngle;
            if (p.t >= 1.0) {
                visAngle = VisualMath.calculateProjectedAngle(next3D, current3D);
            } else {
                visAngle = VisualMath.calculateProjectedAngle(current3D, next3D);
            }

            // 3. Project to Screen
            const transOffset = VisualMath.getTransitionOffset(current3D.x, current3D.y, engine.mapConfig, transitionT, transitionPhase);
            // Use SSOT Projection
            const visY = VisualMath.getIsoVisualY(current3D.y, current3D.z) + transOffset;

            const op = renderList.next();
            op.type = RenderOpType.PROJECTILE;
            op.y = current3D.y; 
            op.z = 5000 + current3D.z; 

            op.pVisX = current3D.x;
            op.pVisY = visY;
            op.pAngle = visAngle;
            op.pSkillVis = traj.spriteKey || p.skill.visual || 'BOLT';
            op.pColor = p.skill.color;
            op.pIsUlt = p.skill.tag === 'ULT';
            op.pSpin = traj.spinSpeed ? (p.t * p.totalDuration * traj.spinSpeed) : 0;
            op.pScale = traj.scale || 1.0; 

            // 4. Trails (Calculated purely visually backwards from SSOT position)
            op.pTrail = [];
            const trailSamples = p.skill.tag === 'ULT' ? 20 : 10;

            if (trailSamples > 0) {
                const step = 0.015; 
                for (let j = 1; j <= trailSamples; j++) {
                    const tPast = Math.max(0, p.t - j * step);
                    // Use SSOT Evaluate for past points
                    const past3D = TrajectoryMath.evaluate(traj, start, end, tPast);

                    const pOffset = VisualMath.getTransitionOffset(past3D.x, past3D.y, engine.mapConfig, transitionT, transitionPhase);
                    const pastY = VisualMath.getIsoVisualY(past3D.y, past3D.z) + pOffset;
                    op.pTrail.push({ x: past3D.x, y: pastY });
                    if (tPast <= 0) break;
                }
            }
        }
    }
};

import { Point3D } from "./VisualMath";

export { Point3D };

export interface TrajectoryConfig {
    type: 'LINEAR' | 'ARC' | 'WOBBLE' | 'INSTANT';
    arcHeight?: number;
    wobbleFreq?: number;
    wobbleAmp?: number;
}

/**
 * 飛行幾何真理庫 v16.0 - Pure 3D Kinematics
 * 只負責計算 3D 空間中的點 (x, y, z)，絕不處理螢幕投影。
 */
export const TrajectoryMath = {

    linear: (start: Point3D, end: Point3D, t: number): Point3D => {
        return {
            x: start.x + (end.x - start.x) * t,
            y: start.y + (end.y - start.y) * t,
            z: start.z + (end.z - start.z) * t
        };
    },

    parabolic: (start: Point3D, end: Point3D, t: number, h: number): Point3D => {
        const x = start.x + (end.x - start.x) * t;
        const y = start.y + (end.y - start.y) * t;
        const linearZ = start.z * (1 - t) + end.z * t;
        // 拋物線高度公式: 4h * t * (1-t)
        const arcZ = 4 * h * t * (1 - t);
        return { x, y, z: linearZ + arcZ };
    },

    wobble: (start: Point3D, end: Point3D, t: number, amp: number, freq: number): Point3D => {
        const base = TrajectoryMath.linear(start, end, t);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < 1) return base;

        // 計算垂直於運動方向的法線向量
        const nx = -dy / dist;
        const ny = dx / dist;
        const wave = Math.sin(t * Math.PI * 2 * freq) * amp;

        return {
            x: base.x + nx * wave,
            y: base.y + ny * wave,
            z: base.z + Math.cos(t * Math.PI * 2 * freq) * amp * 0.5
        };
    },

    /**
     * SSOT: 唯一軌跡計算入口
     */
    evaluate: (config: TrajectoryConfig, start: Point3D, end: Point3D, t: number): Point3D => {
        if (config.type === 'ARC') {
            return TrajectoryMath.parabolic(start, end, t, config.arcHeight || 150);
        }
        if (config.type === 'WOBBLE') {
            return TrajectoryMath.wobble(start, end, t, config.wobbleAmp || 15, config.wobbleFreq || 2);
        }
        return TrajectoryMath.linear(start, end, t);
    }
};

