import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";
import { VisualMath } from "../../math/VisualMath";
import { isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const GROUND_PROJECTION_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

export class VFXRenderer {
    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        const PAD_X = 1200;
        const PAD_Y_TOP = 2500; 
        const PAD_Y_BOT = 1200;

        if (viewport) {
            const { width, height, camera } = viewport;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - PAD_X;
            cullMaxX = camera.x + (viewW / 2) + PAD_X;
            cullMinY = camera.y - (viewH / 2) - PAD_Y_TOP;
            cullMaxY = camera.y + (viewH / 2) + PAD_Y_BOT;
        }

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            // Use SSOT Math
            const offset = VisualMath.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1500) return;

            const op = renderList.next();
            op.type = RenderOpType.VFX;

            const isGroundLocked = GROUND_PROJECTION_TYPES.has(p.type);
            const isUlt = (p as any).pIsUlt || p.type === 'GIANT_HEX' || p.type === 'MAGIC_CIRCLE';

            op.y = p.y + offset + (isGroundLocked ? 2 : 0); 
            op.z = isGroundLocked ? (p.z + 5) : p.z; 
            op.pIsUlt = isUlt; 

            op.particle = p;
            op.vProgress = 1 - (p.life / p.maxLife);
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = VisualMath.getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = d.y + offset + 1; 
            op.z = 2; 
            op.tx = d.x; op.ty = d.y + offset; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }
}

import { Particle } from "./state";
import { PHYSICS } from "../../../constants";

export class VFXPhysics {
    public static update(p: Particle, dt: number, getTerrainHeight?: (x: number, y: number) => number) {
        p.x += p.vx * dt;
        p.y += p.vy * dt;
        p.rotation += p.vRotation * dt;

        const isPhysical = ['DEBRIS', 'SHARD', 'SPRITE', 'ROCK', 'CHIP', 'RUBBLE', 'GIANT_HEX'].includes(p.type);
        const currentGroundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

        if (isPhysical) {
            // SSOT: Use defined game gravity if particle doesn't override
            const g = p.gravity !== undefined ? p.gravity : PHYSICS.GRAVITY;
            p.vz -= g * dt;
            p.z += p.vz * dt;

            const floorLevel = currentGroundH + 2;

            if (p.z < floorLevel) {
                p.z = floorLevel;

                if (Math.abs(p.vz) > 120) {
                    p.vz = -p.vz * 0.45;
                    p.vx *= 0.7;
                    p.vy *= 0.7;
                    p.vRotation *= 0.6;
                } else {
                    p.vz = 0;
                    p.vx *= 0.2;
                    p.vy *= 0.2;
                    p.vRotation = 0;
                }
            }
        } else {
            p.z += p.vz * dt;

            if (p.drag !== undefined) {
                const f = 1 - p.drag;
                p.vx *= f; p.vy *= f; p.vz *= f;
            } else {
                p.vx *= 0.94;
                p.vy *= 0.94;
                p.vz *= 0.94;
            }

            if (p.z < currentGroundH) {
                p.z += (currentGroundH - p.z) * 0.1;
            }
        }

        p.lastGroundHeight = currentGroundH;
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,
        HAZARD_FOG: -15,
        OVERLAY: 5,
        SHADOW: 8,
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static calculateProjectedAngle(p1: Point3D, p2: Point3D): number {
        const dx = p2.x - p1.x;
        const screenY1 = this.getIsoVisualY(p1.y, p1.z);
        const screenY2 = this.getIsoVisualY(p2.y, p2.z);
        const dy = screenY2 - screenY1;
        return Math.atan2(dy, dx);
    }

    public static applyLayerBias(surfaceY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return surfaceY - this.Z_LAYERS[layer];
    }

    public static getEntityVisualY(py: number, terrainH: number, physicsY: number, physicsZ: number, offset: number): number {
        return (py + physicsY) - terrainH - physicsZ + offset;
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET - VISUAL_ANCHORS.HEAD_OFFSET + bob;
    }

    /**
     * SSOT: Calculate Shadow properties based on physics height
     */
    public static getShadowProperties(z: number): { scale: number, alpha: number } {
        // Base opacity lowered to avoid black blobs
        const scale = Math.max(0.4, 1.0 - (z / 500));
        const alpha = Math.max(0.05, 0.35 - (z / 300));
        return { scale, alpha };
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            const q = parseInt(parts[0]);
            const r = parseInt(parts[1]);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            return { x: p.x, y: p.y, z: h + 2 };
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";
import { HexLayout } from "../../../../../types";
import { VisualMath } from "../../../math/VisualMath";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, t: number, isSilhouette: boolean, layout: HexLayout) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const surfaceY = py;

        // SSOT: Use centralized shadow bias
        const tokenY = VisualMath.applyLayerBias(surfaceY, 'SHADOW');

        ctx.save();

        // Uses agent.physics.z directly (SSOT)
        const jumpHeight = agent.physics.z;

        // SSOT: Use centralized shadow formula
        const { scale: shadowScale, alpha: shadowAlpha } = VisualMath.getShadowProperties(jumpHeight);
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,1)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.globalCompositeOperation = 'multiply'; // Use multiply to blend with ground

        const w = 110; 
        const h = w * ISO_SCALE_Y;
        ctx.drawImage(shadowBlob, -w/2, -h/2, w, h); 
        ctx.restore();

        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t, layout);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t, layout);
            }
        }

        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.2)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';

                if (isAOE && radius > 0) {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, radius, skill.tag, isAOE, layout);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils } from "../../utils";
import { VisualMath } from "../../math/VisualMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            // Use VisualMath directly for transition calculation
            const offset = VisualMath.getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;
            const visualSurfaceY = VisualMath.getIsoVisualY(visualBaseY, h);

            if (Math.abs(offset) > 800) continue;

            // 1. 提交障礙物 (繼承 tile 座標供排序)
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.tq = q; op.tr = r; // 核心：傳入邏輯座標
                op.th = h; 
                op.tx = px; 
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 2. 提交地面效果
            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.tq = q; hOp.tr = r;
                hOp.th = h;
                hOp.tx = px; 
                hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            // 3. 提交地形
            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.tq = q; op.tr = r; // 核心：傳入邏輯座標
            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    public hp: number = 100;
    public maxHp: number = 100;
    public shield: number = 0;
    public maxShield: number = 0;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0;
    public moveSpeedMult: number = 1.0;
    public jump: number = 1;
    public weight: number = 1;
    public movementType: MovementType = MovementType.GROUND;

    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0;
    public curCDs: number[] = [0, 0, 0];

    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;
    public facing: number = 1;
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    public aiUpdateTimer: number = 0;
    public aiUpdateInterval: number = 0.3;

    // SSOT Update: Store terrain height 'h' to ensure trails respect topography
    public trailHistory: {x: number, y: number, z: number, h: number}[] = [];

    public stunTimer: number = 0;
    public stunMax: number = 0;

    public banishTimer: number = 0;
    public banishMax: number = 0;

    public silenceTimer: number = 0;
    public silenceMax: number = 0;

    public banished: boolean = false;

    public rootTimer: number = 0;
    public fearTimer: number = 0;
    public tauntTimer: number = 0;
    public blindTimer: number = 0;
    public tauntTargetId: string | null = null;

    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    public drStacks: Record<string, number> = {};
    public drTimers: Record<string, number> = {};

    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public hitFlashTimer: number = 0;

    public physics = {
        x: 0, y: 0, z: 0,
        vx: 0, vy: 0, vz: 0,
        angle: 0, vAngle: 0
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(id: string, team: Team, q: number, r: number, config: MapConfig) {
        this.id = id;
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.aiUpdateInterval = 0.2 + Math.random() * 0.2; 

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.shield = 0;
        this.maxShield = 0;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0;
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.stunMax = 0;
        this.banishTimer = 0;
        this.banishMax = 0;
        this.silenceTimer = 0;
        this.silenceMax = 0;
        this.rootTimer = 0;
        this.fearTimer = 0;
        this.tauntTimer = 0;
        this.blindTimer = 0;
        this.tauntTargetId = null;

        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.drStacks = {};
        this.drTimers = {};

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5;

        this.target = null;
        this.targetHex = null;

        this.aiUpdateTimer = Math.random() * 0.5;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
        this.trailHistory = [];
    }
}

import { Agent, GameEngine } from "../game";
import { PhysicsEngine } from "../physics/PhysicsEngine";

export class PhysicsSystem {
    private engine: PhysicsEngine;

    constructor() {
        this.engine = new PhysicsEngine();
    }

    public update(dt: number, engine: GameEngine) {
        // Physics integration only. 
        // Visual side-effects (dust, sparks) are now handled by AgentVFXSystem.
        for (const a of engine.agents) {
            this.engine.update(a, dt, engine);

            // Handle Trail History Recording (here or in PhysicsEngine, but logic context is better)
            // Determine if trail should be recorded
            const speedSq = a.physics.vx*a.physics.vx + a.physics.vy*a.physics.vy;
            if (speedSq > 10000 || (a.movementType === 1 && a.hp > 0)) { // 1 = FLYING
                const terrainH = engine.map.getTerrainHeight(a.q, a.r);
                a.trailHistory.push({ 
                    x: a.px + a.physics.x, 
                    y: a.py + a.physics.y, 
                    z: a.physics.z,
                    h: terrainH
                });
                if (a.trailHistory.length > 15) a.trailHistory.shift(); // Keep consistent with MotionEngine constant
            } else if (a.trailHistory.length > 0) {
                a.trailHistory.shift();
            }
        }
    }
}

import { Agent, GameEngine } from "../game";
import { MovementType } from "../../types";
import { HexUtils } from "../utils";
import { PHYSICS } from "../../constants";

export class PhysicsEngine {
    public static applyImpulse(target: Agent, origin: {x: number, y: number}, force: number, randomness: number = 0) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const effectiveForce = Math.min(PHYSICS.TERMINAL_VELOCITY_IMPULSE, Math.max(50, force));
        let vx = 0, vy = 0;
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }
        target.physics.vx += vx;
        target.physics.vy += vy;

        target.physics.vAngle += (Math.random() - 0.5) * 10.0; 

        if (randomness > 0) target.physics.vAngle += (Math.random() - 0.5) * randomness;
    }

    public update(a: Agent, dt: number, engine: GameEngine) {
        if (a.fullyDead) return;
        const isDead = a.hp <= 0;

        const stiffness = isDead ? 0 : PHYSICS.STIFFNESS_ALIVE * 1.2;
        const damping = PHYSICS.DAMPING_ALIVE * 1.1; 

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        if (isFlying && !isDisabled) {
            const hoverHeight = 55, hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92;
        } else if (isAirborne || a.physics.z > 0.1) {
            a.physics.vz -= PHYSICS.GRAVITY * dt;
        }

        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // Note: Trail Logic moved to PhysicsSystem.ts to centralize history management

        if (a.physics.z < 0) {
            a.physics.z = 0;
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;
                    a.hp = Math.max(0, a.hp - rawDmg);
                    engine.events.push({ type: 'DAMAGE', pos: {x: a.px, y: a.py}, value: -rawDmg, color: '#ef4444', text: "墜落" });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg}`);

                    engine.bus.emit('CAMERA_SHAKE', { intensity: pct * 0.5 });

                    if (a.hp <= 0) {
                        engine.agentManager.handleDeadState(a, engine);
                    } else {
                        // SSOT: Set visual timer instead of imperative setAnim
                        a.hitFlashTimer = 0.2; 
                    }
                }
                a.physics.vz = -a.physics.vz * 0.3;
                a.physics.vx *= 0.5; a.physics.vy *= 0.5; a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px, dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            if (speedSq < 5000) {
                if (distSq > 0.5) {
                    const driftSpeed = PHYSICS.DRIFT_SPEED * dt; 
                    a.px += dx * driftSpeed; a.py += dy * driftSpeed;
                    if (distSq < 2) { a.px = targetPos.x; a.py = targetPos.y; }
                } else {
                    a.px = targetPos.x; a.py = targetPos.y;
                }
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { MovementType } from "../../../types";

const STACKING_RESOLUTION_FORCE = 8;
const TRAIL_HISTORY_LENGTH = 15;
const FACING_THRESHOLD = 1.5; 

export class MotionEngine {

    public static updateMovement(a: Agent, dt: number, engine: GameEngine) {
        if (a.path.length === 0) {
            a.isMoving = false;
            a.moveProgress = 0;
            return;
        }

        const moveDelta = a.moveSpeed * a.moveSpeedMult * dt;
        a.moveProgress += moveDelta;

        const startH = { q: a.q, r: a.r };
        const nextHex = a.path[0];

        const c = HexUtils.toPx(startH.q, startH.r, engine.mapConfig);
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        if (Math.abs(n.x - a.px) > FACING_THRESHOLD) {
            a.facing = n.x > a.px ? 1 : -1;
        }

        const t = Math.min(1.0, a.moveProgress);
        a.px = c.x + (n.x - c.x) * t;
        a.py = c.y + (n.y - c.y) * t;

        if (a.movementType === MovementType.FLYING && a.hp > 0) {
            const h = engine.map.getTerrainHeight(a.q, a.r); // Approximation for current tile
            a.trailHistory.push({ x: a.px, y: a.py, z: a.physics.z, h });
            if (a.trailHistory.length > TRAIL_HISTORY_LENGTH) a.trailHistory.shift();
        }

        if (a.moveProgress >= 1.0) {
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);
            a.path.shift();

            if (a.path.length > 0) {
                a.moveProgress -= 1.0;
                this.updateMovement(a, 0, engine);
            } else {
                this.finalizeMove(a);
            }
        }
    }

    private static finalizeMove(a: Agent) {
        a.isMoving = false;
        a.moveSpeedMult = 1.0; 
        a.moveProgress = 0;

        a.physics.vx *= 0.1;
        a.physics.vy *= 0.1;

        a.physics.vx += (Math.random() - 0.5) * STACKING_RESOLUTION_FORCE;
        a.physics.vy += (Math.random() - 0.5) * STACKING_RESOLUTION_FORCE;
    }
}

import { Agent } from "../../../game";
import { Team, MovementType } from "../../../../types";
import { UNIT_SCALE, VISUAL_ANCHORS } from "../../../../constants";
import { FACTION_VISUALS } from "../../../../data/vfx/faction_visuals";
import { VisualMath } from "../../../math/VisualMath";

export const UnitFlightPainter = {

    drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
        // Deprecated
    },

    drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        // This is called within the UnitBodyPainter's transformed context (Body Center)
        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;

        ctx.save();
        ctx.translate(0, VISUAL_ANCHORS.ENGINE_OFFSET_Y); // Use Standard Constant

        // Engine Glows (Oscillating)
        const pulse = 0.8 + Math.sin(t * 20) * 0.2;

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // Left Engine
        ctx.beginPath(); ctx.arc(-12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();
        // Right Engine
        ctx.beginPath(); ctx.arc(12, 0, 4 * pulse, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    /**
     * 通用軌跡繪製：支持飛行緞帶 (Ribbon) 與地面滑痕 (Skid Marks)
     * SSOT: Now uses stored 'h' in trail history to accurately project past positions.
     */
    drawRibbonTrail(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.trailHistory.length < 2) return;

        const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
        const color = faction.flightTrailColor;
        const isFlying = agent.movementType === MovementType.FLYING;

        ctx.save();
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // We need to transform from "Unit Body Center" local space back to "Screen Space" relative to current pos

        const currentPx = agent.px + agent.physics.x;

        // HACK/FIX: We must assume the last point in trailHistory is close to current, or use 0 delta if unknown.
        // Better: We can just draw the trail relative to the *World* position and assume H doesn't change wildly between frames?
        // No, that causes jitter.

        // Let's calculate purely relative to the *current* frame of reference.
        // We need to pass `terrainHeight` to `UnitBodyPainter` and then to here.
        // Since we cannot change method signatures easily across too many files in one shot,
        // we will infer `currentH` from the last trail point if available, or 0.
        // This is a safe approximation for trails.

        const currentWorldY = agent.py + agent.physics.y;
        const currentH = agent.trailHistory.length > 0 ? agent.trailHistory[agent.trailHistory.length-1].h : 0;
        const currVy = VisualMath.getVisualBodyCenterY(currentWorldY - currentH, agent.physics.z);

        const points: {x: number, y: number}[] = [];

        for (const p of agent.trailHistory) {
            // SSOT Projection for Trail Point
            // SurfaceY = p.y - p.h
            const pVy = VisualMath.getVisualBodyCenterY(p.y - p.h, p.z);
            points.push({ x: p.x, y: pVy });
        }
        points.push({ x: currentPx, y: currVy });

        if (points.length < 2) { ctx.restore(); return; }

        ctx.beginPath();

        for (let i = 0; i < points.length; i++) {
            const p = points[i];
            const dx = p.x - currentPx;
            const dy = p.y - currVy;

            // Add engine offset visual adjust
            const engOffset = VISUAL_ANCHORS.ENGINE_OFFSET_Y;

            if (i === 0) ctx.moveTo(dx, dy + engOffset);
            else ctx.lineTo(dx, dy + engOffset);
        }

        if (isFlying) {
            ctx.strokeStyle = color;
            ctx.lineWidth = 4 * UNIT_SCALE;
            ctx.globalAlpha = 0.4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.stroke();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1 * UNIT_SCALE;
            ctx.globalAlpha = 0.8;
            ctx.shadowBlur = 0;
            ctx.stroke();
        } else {
            ctx.strokeStyle = color;
            ctx.lineWidth = 3 * UNIT_SCALE;
            ctx.globalAlpha = 0.3; 
            ctx.globalCompositeOperation = 'screen';
            ctx.stroke();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.setLineDash([5, 5]); 
            ctx.globalAlpha = 0.5;
            ctx.stroke();
        }

        ctx.restore();
    }
};

import { Team, Role } from "../../../../types";
