export class VFXAmbience {
    private timer: number = 0;

    public update(dt: number, type: string, state: VFXStateManager) {
        if (type === 'NONE') return;

        this.timer += dt;

        let rate = 0.15;
        if (type === 'SNOW' || type === 'ASH') rate = 0.03;
        if (type === 'SAND') rate = 0.005; 

        if (this.timer > rate) {
            this.timer = 0;

            const p = state.getParticle();
            p.type = 'ATMOSPHERE'; 

            // Hardcoded bounds are bad. Let's use a safe large area but center it.
            // Ideally we'd read engine.mapConfig but this class doesn't have engine reference in update signature currently (except in VFXSystem wrapper).
            // For now, we assume standard large area coverage.
            let x = Math.random() * 2000 - 400;
            const y = Math.random() * 1400 - 400;

            p.z = Math.random() * 400 + 50; 

            if (type === 'SNOW') {
                p.x = x; p.y = y;
                p.color = '#fff';
                p.size = Math.random() * 2.5 + 1.5;
                p.vx = 40 + Math.random() * 30; // Wind
                p.vy = 80 + Math.random() * 40; // Fall
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'ASH') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#1c1917' : '#451a03'; 
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 30 + Math.random() * 20;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#f59e0b' : '#ef4444';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 40;
                p.vy = -40 - Math.random() * 30; 
                p.life = 2.5; p.maxLife = 2.5;
                p.blendMode = 'screen'; 
            } else if (type === 'SPORES') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2.5 + 0.5;
                p.vx = (Math.random() - 0.5) * 15;
                p.vy = (Math.random() - 0.5) * 15;
                p.life = 6.0; p.maxLife = 6.0;
                p.blendMode = 'screen';
            } else if (type === 'SAND') {
                // Spawn off-screen left
                p.x = -200; 
                p.y = Math.random() * 1600 - 200; 

                p.color = Math.random() > 0.6 ? '#fcd34d' : '#d97706'; 
                p.size = Math.random() * 2 + 1; 

                p.vx = 1200 + Math.random() * 600; 
                p.vy = 50 + Math.random() * 30; 

                p.life = 1.8; p.maxLife = 1.8; 
                p.blendMode = 'source-over';
            }

            state.particles.push(p);
        }
    }
}

import { Agent, GameEngine } from "../game";
import { MovementType } from "../../types";
import { HexUtils } from "../utils";
import { PHYSICS } from "../../constants";

export class PhysicsEngine {
    public static applyImpulse(target: Agent, origin: {x: number, y: number}, force: number, randomness: number = 0) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const effectiveForce = Math.min(PHYSICS.TERMINAL_VELOCITY_IMPULSE, Math.max(50, force));
        let vx = 0, vy = 0;
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }
        target.physics.vx += vx;
        target.physics.vy += vy;

        target.physics.vAngle += (Math.random() - 0.5) * 10.0; 

        if (randomness > 0) target.physics.vAngle += (Math.random() - 0.5) * randomness;
    }

    public update(a: Agent, dt: number, engine: GameEngine) {
        if (a.fullyDead) return;
        const isDead = a.hp <= 0;

        const stiffness = isDead ? 0 : PHYSICS.STIFFNESS_ALIVE * 1.2;
        const damping = PHYSICS.DAMPING_ALIVE * 1.1; 

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        if (isFlying && !isDisabled) {
            const hoverHeight = 55, hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92;
        } else if (isAirborne || a.physics.z > 0.1) {
            a.physics.vz -= PHYSICS.GRAVITY * dt;
        }

        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // Note: Trail Logic moved to PhysicsSystem.ts to centralize history management

        if (a.physics.z < 0) {
            a.physics.z = 0;
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;
                    a.hp = Math.max(0, a.hp - rawDmg);
                    engine.events.push({ type: 'DAMAGE', pos: {x: a.px, y: a.py}, value: -rawDmg, color: '#ef4444', text: "墜落" });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg}`);

                    engine.bus.emit('CAMERA_SHAKE', { intensity: pct * 0.5 });

                    if (a.hp <= 0) {
                        engine.agentManager.handleDeadState(a, engine);
                    } else {
                        // SSOT: Set visual timer instead of imperative setAnim
                        a.hitFlashTimer = 0.2; 
                    }
                }
                a.physics.vz = -a.physics.vz * 0.3;
                a.physics.vx *= 0.5; a.physics.vy *= 0.5; a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px, dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;
            const speedSq = a.physics.vx * a.physics.vx + a.physics.vy * a.physics.vy;

            if (speedSq < 5000) {
                if (distSq > 0.5) {
                    const driftSpeed = PHYSICS.DRIFT_SPEED * dt; 
                    a.px += dx * driftSpeed; a.py += dy * driftSpeed;
                    if (distSq < 2) { a.px = targetPos.x; a.py = targetPos.y; }
                } else {
                    a.px = targetPos.x; a.py = targetPos.y;
                }
            }
        }
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE, VISUAL_ANCHORS } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {
    public static readonly HORIZON_Y_PCT = 0.62;
    public static readonly PROJECTILE_HIT_TOLERANCE_SQ = 900; 

    // SSOT: Visual Layer Biases (Positive value = Shift Upwards visually)
    // Used to prevent Z-fighting on the ground plane.
    public static readonly Z_LAYERS = {
        TERRAIN: 0,
        HAZARD: 3,       // Lifted above terrain
        HAZARD_FOG: -15, // Pushed down/behind
        OVERLAY: 5,      // UI Overlays
        SHADOW: 8,       // Shadows on top of overlays
        DECAL: 2,        // Ground decals (cracks, scorch marks)
        AURA: 1.5,       // Unit Auras (just below decals to blend?) or slightly above
        UNIT_FEET: 0,
        LIQUID_OFFSET: 1
    };

    public static getTransitionOffset(x: number, y: number, config: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const cx = config.offsetX;
        const cy = config.offsetY;
        const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
        const maxDist = 1000;
        const d = Math.min(1, dist / maxDist);
        const BASE_OFFSET = 1500;
        if (phase === 'OUT') {
            const startT = d * 0.3;
            if (t < startT) return 0;
            let localT = (t - startT) * 1.8;
            localT = Math.max(0, Math.min(1, localT));
            return (localT * localT * (1.5 * localT - 0.5)) * BASE_OFFSET;
        } else if (phase === 'IN') {
            const startT = d * 0.2;
            if (t < startT) return BASE_OFFSET;
            let localT = Math.max(0, Math.min(1, (t - startT) * 1.5));
            return (1 - (1 - Math.pow(1 - localT, 4))) * BASE_OFFSET;
        }
        return 0;
    }

    public static getIsoVisualY(y: number, z: number, extraOffset: number = 0): number {
        return y - z + extraOffset;
    }

    public static calculateProjectedAngle(p1: Point3D, p2: Point3D): number {
        const dx = p2.x - p1.x;
        const screenY1 = this.getIsoVisualY(p1.y, p1.z);
        const screenY2 = this.getIsoVisualY(p2.y, p2.z);
        const dy = screenY2 - screenY1;
        return Math.atan2(dy, dx);
    }

    /**
     * Applies standard layer bias to a surface Y coordinate.
     * Use this for anything drawn "flat" on the ground to avoid flickering.
     */
    public static applyLayerBias(surfaceY: number, layer: keyof typeof VisualMath.Z_LAYERS): number {
        return surfaceY - this.Z_LAYERS[layer];
    }

    public static getEntityVisualY(py: number, terrainH: number, physicsY: number, physicsZ: number, offset: number): number {
        return (py + physicsY) - terrainH - physicsZ + offset;
    }

    public static getVisualBodyCenterY(surfaceY: number, z: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET;
    }

    public static getOverheadVisualY(surfaceY: number, z: number, bob: number): number {
        return surfaceY - z - UNIT_BODY_OFFSET - UNIT_HOVER_OFFSET - VISUAL_ANCHORS.HEAD_OFFSET + bob;
    }

    public static getShadowProperties(z: number): { scale: number, alpha: number } {
        const scale = Math.max(0.4, 1.0 - (z / 500));
        const alpha = Math.max(0.05, 0.35 - (z / 300));
        return { scale, alpha };
    }

    public static getUnitAnchor(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;
        return { x: agent.px + agent.physics.x, y: agent.py + agent.physics.y, z: z };
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };
        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) return this.getUnitAnchor(agent, engine);
        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            const q = parseInt(parts[0]);
            const r = parseInt(parts[1]);
            const p = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            return { x: p.x, y: p.y, z: h + 2 };
        }
        return { x: 0, y: 0, z: -9999 };
    }
}

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { VisualMath, Point3D } from "../../math/VisualMath";
import { VISUAL_ANCHORS } from "../../../constants";

// Sub-Handlers
import { CombatVFXHandler } from "./handlers/CombatVFXHandler";
import { UnitVFXHandler } from "./handlers/UnitVFXHandler";
import { CinematicVFXHandler } from "./handlers/CinematicVFXHandler";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Resolve Spatial Context
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine);

        const groundHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const groundZ = grid.getTerrainHeight(groundHex.q, groundHex.r, engine);

        // SSOT Fix: Use standard center offset for generic targets (approximate chest height)
        if (!event.targetId) target.z = groundZ + VISUAL_ANCHORS.CENTER_OFFSET;

        // 2. Route to specialized atomic handlers
        switch (event.type) {
            case 'DAMAGE': 
            case 'PROJECTILE_HIT': 
            case 'IMPACT_AOE':
                CombatVFXHandler.handle(event, vfx, camera, target, groundZ);
                break;

            case 'DEATH':
            case 'SPAWN':
            case 'CAST_BREAK':
                UnitVFXHandler.handle(event, engine, vfx, camera, origin, groundZ);
                break;

            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                CinematicVFXHandler.handle(event, engine, vfx, origin, target);
                break;

            case 'HAZARD_SPAWN':
                if (event.text) { // We stored VFX ID in 'text' field
                    vfx.playEffect(event.text, event.pos.x, event.pos.y, groundZ);
                }
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine): Point3D {
        if (agentId) {
            const agent = engine.agents.find(a => a.id === agentId);
            if (agent) return VisualMath.getUnitAnchor(agent, engine);
        }
        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = engine.map.getTerrainHeight(hex.q, hex.r);
        return { x: defaultX, y: defaultY, z: terrainH };
    }
}

import { GameEvent } from "../../../../types";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D, VisualMath } from "../../../math/VisualMath";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";

export class CombatVFXHandler {
    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {
        const damage = Math.abs(event.value || 0);
        const isCrit = damage > 150;
        const isMassive = damage > 400;
        let intensity = isMassive ? 2.5 : (isCrit ? 1.6 : 1.0);

        if (event.type === 'DAMAGE') {
            if (!event.skill?.projectileSpeed && event.skill?.ccType !== 'DOT') {
                this.playImpact(event, vfx, target, groundZ, intensity);
                camera.addTrauma(isMassive ? 0.45 : (isCrit ? 0.3 : 0.12));
            } else if (event.skill?.ccType === 'DOT') {
                vfx.playEffect('FX_STATUS_BURN_LOOP', target.x, target.y, target.z, event.color);
            }
            return;
        }

        // Standardize generic impact height to Hazard/Floor layer
        const impactZ = groundZ + VisualMath.Z_LAYERS.HAZARD;

        if (event.type === 'PROJECTILE_HIT') {
            const pos = event.skill?.type === 'AOE' ? { x: event.pos.x, y: event.pos.y, z: impactZ } : target;
            this.playImpact(event, vfx, pos, groundZ, intensity);
            camera.addTrauma(0.2 * intensity);
            return;
        }

        if (event.type === 'IMPACT_AOE') {
            const impactPoint = { x: event.pos.x, y: event.pos.y, z: impactZ };
            this.playImpact(event, vfx, impactPoint, groundZ, intensity * 1.2);
            camera.addTrauma(0.35 * intensity);
        }
    }

    private static playImpact(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number, scale: number = 1.0) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = skill?.visualHitEffect || this.getFallbackByElement(skill?.element);

        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);

        if (scale > 1.8) {
            vfx.playEffect('FX_HIT_GENERIC', target.x, target.y, target.z, '#ffffff');
        }
    }

    private static getFallbackByElement(element?: string): string {
        switch(element) {
            case 'FIRE': return 'FX_HIT_FIRE';
            case 'ICE': return 'FX_HIT_BLUE_ICE';
            case 'LIGHTNING': return 'FX_HIT_BLUE_TECH';
            case 'BLOOD': return 'FX_HIT_RED_BLOOD';
            default: return 'FX_HIT_GENERIC';
        }
    }
}

import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { Point3D } from "../../math/VisualMath";
import { VFXSequence, VFXAction } from "../../../types/VFXSchema";
import { VisualMath } from "../../math/VisualMath";
import { PHYSICS } from "../../../constants";

interface QueuedAction {
    executeAt: number;
    action: VFXAction;
    target: Point3D;
    source?: Point3D;
}

export class SequenceSystem {
    private static actionQueue: QueuedAction[] = [];

    public static clear() {
        this.actionQueue = [];
    }

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        let sourcePos: Point3D | undefined;
        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) sourcePos = VisualMath.getUnitAnchor(agent, engine);
        }

        const baseTime = engine.battleTime;
        sequence.actions.forEach(action => {
            const executeAt = baseTime + (action.delay || 0);
            if (executeAt <= baseTime) {
                this.dispatch(action, target, sourcePos, vfx, engine);
            } else {
                this.actionQueue.push({ executeAt, action, target, source: sourcePos });
            }
        });
    }

    public static update(engine: GameEngine, vfx: VFXSystem) {
        const now = engine.battleTime;
        for (let i = this.actionQueue.length - 1; i >= 0; i--) {
            const item = this.actionQueue[i];
            if (now >= item.executeAt) {
                this.dispatch(item.action, item.target, item.source, vfx, engine);
                this.actionQueue.splice(i, 1);
            }
        }
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        const effectId = action.id || 'FX_HIT_GENERIC';

        // SSOT: Use standardized DECAL offset instead of hardcoded -2
        // Note: target.z is usually terrain height + offset. 
        // For ground effects, we want exactly terrain height + bias.
        const groundZ = target.z - VisualMath.Z_LAYERS.DECAL; 

        switch (action.type) {
            case 'PARTICLE':
                vfx.playEffect(effectId, target.x, target.y, target.z, action.color, groundZ);
                break;
            case 'BEAM':
                if (source) vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                break;
            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.3);
                break;
            case 'GRID_PULSE':
                // Use HAZARD layer for pulse impact
                vfx.playEffect(action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', target.x, target.y, groundZ + VisualMath.Z_LAYERS.HAZARD, action.color, groundZ);
                break;
            case 'HEAVEN_FALL':
                const h = action.height || 1200;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;

                // SSOT: Use Game Physics Gravity
                p.vz = -PHYSICS.GRAVITY; 

                // Calculate life based on gravity: t = sqrt(2h/g) roughly, but here vz is linear velocity?
                // Actually assuming linear fall in VFXPhysics for simpler particles, or accelerated?
                // VFXPhysics uses: p.vz -= g * dt. So it is accelerated.
                // Distance d = 0.5 * g * t^2.  t = sqrt(2d/g).
                // d = h. g = PHYSICS.GRAVITY.
                p.life = Math.sqrt((2 * h) / PHYSICS.GRAVITY) + 0.1;

                p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1.8) * 80;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.locked = false;
                (p as any).pIsUlt = true; 
                vfx.state.particles.push(p);
                break;
        }
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { VFXFactory } from "../../../../graphics/VFXFactory";
import { HexLayout } from "../../../../../types";
import { VisualMath } from "../../../../math/VisualMath";

export const GroundPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout) {

        // SSOT: Centralized Z-bias for ground decals
        const drawYBiased = VisualMath.applyLayerBias(drawY, 'DECAL');

        // 1. 向量幾何處理
        if (['SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'MAGIC_CIRCLE'].includes(p.type)) {
            this.drawVectorGeometry(ctx, p, progress, drawX, drawYBiased, layout);
            return;
        }

        const img = p.image || p.texture;
        if (!img) return;

        let alpha = 1.0 - progress;
        if (p.type === 'CRACKS') alpha = 1.0 - Math.pow(progress, 4);

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawYBiased);
        ctx.scale(1, ISO_SCALE_Y); 

        if (p.rotation) ctx.rotate(p.rotation);

        ctx.globalCompositeOperation = p.blendMode || 'screen';
        ctx.globalAlpha = Math.min(1, alpha);

        const size = p.size;
        ctx.drawImage(img, -size, -size, size * 2, size * 2);

        ctx.restore();
    },

    drawVectorGeometry(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout) {
        ctx.save();
        ctx.translate(drawX, drawY);

        ctx.globalCompositeOperation = p.blendMode || 'screen';

        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 15;

            const currentRadius = p.size * (0.3 + progress * 0.7);
            const lineWidth = Math.max(1, (1 - progress) * (p.type === 'SHOCKWAVE' ? 12 : 4));

            ctx.lineWidth = lineWidth;
            HexGeometry.traceHex(ctx, 0, 0, currentRadius, true, layout);
            ctx.stroke();

            // 內圈回饋
            if (p.type === 'SHOCKWAVE') {
                ctx.lineWidth = lineWidth * 0.3;
                ctx.globalAlpha = alpha * 0.5;
                HexGeometry.traceHex(ctx, 0, 0, currentRadius * 0.8, true, layout);
                ctx.stroke();
            }
        }
        else if (p.type === 'GRID_FIELD') {
            const alpha = 1.0 - Math.pow(progress, 4);
            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.fillStyle = p.color;

            const r = p.size;
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
            ctx.stroke();

            ctx.globalAlpha = alpha * 0.15;
            ctx.fill();
        }
        else if (p.type === 'HEX_GLOW') {
            const alpha = 1.0 - Math.pow(progress, 2);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            HexGeometry.traceHex(ctx, 0, 0, p.size, true, layout);
            ctx.fill();
        }

        ctx.restore();
    }
};

import { Agent } from "../../../game";
import { HEX_SIZE } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";
import { VisualMath } from "../../../math/VisualMath";

export const UnitAuraPainter = {

    /**
     * 繪製標準技能詠唱特效 (Vector Geometry)
     */
    drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number, layout: HexLayout) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        // SSOT: Use centralized AURA bias
        const drawY = VisualMath.applyLayerBias(y, 'AURA');

        ctx.save();
        ctx.translate(x, drawY); 

        // 核心數學：法陣半徑隨律動震盪
        const baseSize = HEX_SIZE * 0.95;
        const pulse = Math.sin(t * 12) * 0.05;
        const currentSize = baseSize * (1.0 + pulse);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 12;

        // 1. 旋轉能量環 (外環：順時針)
        const rotA = t * 3;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.6;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize, rotA, true, layout);
        ctx.stroke();

        // 2. 幾何核心 (內環：逆時針，高頻旋轉)
        const rotB = -t * 6;
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.4;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize * 0.7, rotB, true, layout);
        ctx.stroke();

        // 3. 能量溢出點 (Procedural)
        this.drawRisingParticles(ctx, color, progress, t);

        ctx.restore();

        // 4. 若為 AOE，繪製精確的邊界指示器
        if (skill.type === 'AOE') {
            this.drawAoeExpansion(ctx, x, drawY, color, progress, skill.aoeRadius || 1, layout);
        }
    },

    /**
     * 繪製奧義詠唱聖域 (Epic Geometry)
     */
    drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number, layout: HexLayout) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        // SSOT
        const drawY = VisualMath.applyLayerBias(y, 'AURA');

        ctx.save();
        ctx.translate(x, drawY);

        // 奧義法陣規模較大
        const ultSize = HEX_SIZE * 2.5; 
        const rot = t * 1.5;

        ctx.shadowColor = color;
        ctx.shadowBlur = 20;
        ctx.strokeStyle = color;

        // Layer 1: 外部神聖格線
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize, rot, true, layout);
        ctx.stroke();

        // Layer 2: 內部符文環 (虛線幾何)
        ctx.save();
        ctx.lineWidth = 1;
        ctx.setLineDash([12, 8]);
        ctx.globalAlpha = 0.5;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.85, -rot * 0.8, true, layout);
        ctx.stroke();
        ctx.restore();

        // Layer 3: 中心匯聚點
        ctx.globalAlpha = 0.3 + Math.sin(t * 15) * 0.2;
        ctx.fillStyle = color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.4, rot * 4, true, layout);
        ctx.fill();

        // 4. 垂直能量柱投影
        const pillarH = 150 * progress;
        if (pillarH > 5) {
            ctx.fillStyle = color;
            const points = HexGeometry.getVertices(ultSize * 0.7, true, layout);
            points.forEach((p, i) => {
                if (i % 2 === 0) {
                    const alpha = (0.2 + 0.3 * Math.sin(t * 8 + i)) * progress;
                    ctx.globalAlpha = alpha;
                    ctx.fillRect(p.x - 1, p.y - pillarH, 2, pillarH);
                }
            });
        }

        ctx.restore();
    },

    /**
     * 繪製 AOE 擴張波紋 (Vector Ripple)
     */
    drawAoeExpansion(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, progress: number, rangeInTiles: number, layout: HexLayout) {
        ctx.save();
        ctx.translate(x, y - 0.5); // 稍微再高一點避免與法陣重疊 (Local micro-adjustment allowed)

        // 數學半徑：根據網格尺寸精確映射
        const maxPixelRadius = rangeInTiles * HEX_SIZE;
        const easedRadius = maxPixelRadius * (1 - Math.pow(1 - progress, 4));

        ctx.strokeStyle = color;
        ctx.fillStyle = color;

        // 1. 波導前端
        ctx.beginPath();
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = (1 - progress) * 0.7;
        HexGeometry.traceHex(ctx, 0, 0, easedRadius, true, layout);
        ctx.stroke();

        // 2. 內部漫反射
        ctx.globalAlpha = (1 - progress) * 0.08;
        ctx.fill();

        ctx.restore();
    },

    drawRisingParticles(ctx: CanvasRenderingContext2D, color: string, progress: number, t: number) {
        ctx.fillStyle = color;
        const count = 3;
        for(let i=0; i<count; i++) {
            const offset = i * (Math.PI * 2 / count);
            const cycle = (t * 2.5 + offset) % 1; 

            const h = cycle * 70;
            const r = (1 - cycle) * 35;
            const angle = t * 5 + offset;

            const px = Math.cos(angle) * r;
            const py = (Math.sin(angle) * r * 0.5) - h; 

            const alpha = Math.sin(cycle * Math.PI) * 0.8;
            ctx.globalAlpha = alpha;

            ctx.beginPath(); 
            ctx.arc(px, py, 1.5, 0, Math.PI*2); 
            ctx.fill();
        }
    }
};

