import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { HUDSystem } from "../hud";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { HUD_TEXT_OFFSET, HUD_LAYOUT } from "../../../constants";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class EventHUDMapper {

    public reset() {
        // No local state needed anymore
    }

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'DAMAGE':
            case 'HEAL':
            case 'CC_APPLIED':
                this.handleCombatText(event, visualGroundY, hud);
                break;
            case 'CAST_START':
                this.handleCastText(event, visualGroundY, hud);
                break;
            case 'CAST_BREAK':
                // 核心：觸發文字崩解，瞬間移除詠唱條
                if (event.sourceId) {
                    hud.breakCastText(event.sourceId);
                    // 同時彈出 "中斷" 提示
                    const baseY = visualGroundY - HUD_TEXT_OFFSET;
                    hud.addFloatingText(event.pos.x, baseY, "INTERRUPTED", "#ef4444", 16, 'CC');
                }
                break;
            case 'KILL_STREAK':
                if (event.text && event.color) {
                    const textY = visualGroundY - HUD_TEXT_OFFSET - 40;
                    const size = 32 + ((event.value || 1) * 4); 
                    hud.addFloatingText(event.pos.x, textY, event.text, event.color, size, 'KILL_STREAK');
                    camera.addTrauma(0.2 + (event.value || 0) * 0.1);
                }
                break;
        }
    }

    private handleCombatText(event: GameEvent, visualY: number, hud: HUDSystem) {
        const baseY = visualY - HUD_TEXT_OFFSET; 
        let text = "";
        let color = "#fff";
        let size = 16;
        let type: 'DAMAGE' | 'HEAL' | 'CC' = 'DAMAGE';
        let xOffset = 0;

        if (event.type === 'DAMAGE') {
            const val = Math.abs(event.value || 0);
            text = val.toString();
            const isCrit = val > 100;
            const isDot = event.skill?.ccType === 'DOT';

            if (isDot) {
                color = STATUS_VISUALS['POISON']?.primaryColor || '#a3e635';
            } else if (isCrit) {
                color = '#ef4444'; 
            } else {
                color = '#fff';
            }

            size = isCrit ? 24 : 16;
            type = 'DAMAGE';
            xOffset = (Math.random() - 0.5) * HUD_LAYOUT.DAMAGE_TEXT_SCATTER;

        } else if (event.type === 'HEAL') {
            text = "+" + Math.abs(event.value || 0);
            color = STATUS_VISUALS['REGEN']?.primaryColor || '#4ade80';
            type = 'HEAL';
            xOffset = (Math.random() - 0.5) * HUD_LAYOUT.DAMAGE_TEXT_SCATTER;
        } else {
            text = event.text || "";
            color = event.color || "#fff";
            type = 'CC';
            size = 14;
            xOffset = HUD_LAYOUT.STATUS_TEXT_OFFSET_X;
        }

        if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
    }

    private handleCastText(event: GameEvent, visualY: number, hud: HUDSystem) {
        if (event.skill && event.skill.tag !== 'BASIC') {
            const isUlt = event.skill.tag === 'ULT';
            const offsetY = isUlt ? HUD_LAYOUT.CAST_BAR_Y_OFFSET_ULT : HUD_LAYOUT.CAST_BAR_Y_OFFSET_NORMAL;
            const baseY = visualY - HUD_TEXT_OFFSET - offsetY; 
            const xOffset = HUD_LAYOUT.CAST_BAR_X_OFFSET; 

            hud.addFloatingText(
                event.pos.x + xOffset, 
                baseY, 
                event.skill.name, 
                event.skill.color, 
                14, 
                'SHOUT', 
                isUlt,
                event.sourceId,
                event.skill.cast 
            );
        }
    }
}

import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { Point3D } from "../../math/VisualMath";
import { VFXSequence, VFXAction } from "../../../types/VFXSchema";
import { VisualMath } from "../../math/VisualMath";
import { PHYSICS } from "../../../constants";

interface QueuedAction {
    executeAt: number;
    action: VFXAction;
    target: Point3D;
    source?: Point3D;
}

export class SequenceSystem {
    private static actionQueue: QueuedAction[] = [];

    public static clear() {
        this.actionQueue = [];
    }

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        let sourcePos: Point3D | undefined;
        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) sourcePos = VisualMath.getUnitAnchor(agent, engine);
        }

        const baseTime = engine.battleTime;
        sequence.actions.forEach(action => {
            const executeAt = baseTime + (action.delay || 0);
            if (executeAt <= baseTime) {
                this.dispatch(action, target, sourcePos, vfx, engine);
            } else {
                this.actionQueue.push({ executeAt, action, target, source: sourcePos });
            }
        });
    }

    public static update(engine: GameEngine, vfx: VFXSystem) {
        const now = engine.battleTime;
        for (let i = this.actionQueue.length - 1; i >= 0; i--) {
            const item = this.actionQueue[i];
            if (now >= item.executeAt) {
                this.dispatch(item.action, item.target, item.source, vfx, engine);
                this.actionQueue.splice(i, 1);
            }
        }
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        const effectId = action.id || 'FX_HIT_GENERIC';

        // SSOT: Use standardized DECAL offset instead of hardcoded -2
        const groundZ = target.z - VisualMath.Z_LAYERS.DECAL; 

        switch (action.type) {
            case 'PARTICLE':
                vfx.playEffect(effectId, target.x, target.y, target.z, action.color, groundZ);
                break;
            case 'BEAM':
                if (source) vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                break;
            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.3);
                break;
            case 'GRID_PULSE':
                // Use HAZARD layer for pulse impact
                vfx.playEffect(action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', target.x, target.y, groundZ + VisualMath.Z_LAYERS.HAZARD, action.color, groundZ);
                break;
            case 'HEAVEN_FALL':
                const h = action.height || 1200;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;

                // SSOT Fix: Initial Z-velocity must be 0 for the free-fall time formula to be correct.
                // Formula: t = sqrt(2h/g). This implies v0 = 0.
                p.vz = 0; 

                p.life = Math.sqrt((2 * h) / PHYSICS.GRAVITY) + 0.1; // Add slight buffer

                p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1.8) * 80;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.locked = false;
                (p as any).pIsUlt = true; 
                vfx.state.particles.push(p);
                break;
        }
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";
import { AgentVFXSystem } from "./vfx/AgentVFXSystem";
import { Point3D } from "../math/VisualMath";
import { GameEngine } from "../game";

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();
    private agentVFX: AgentVFXSystem = new AgentVFXSystem();

    public reset() { this.state.reset(); }

    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }

    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x; p.ty = end.y; p.tz = end.z;
        p.x = start.x; p.y = start.y; p.z = start.z;
        p.life = duration; p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; p.style = styleId; p.locked = true;
        this.state.particles.push(p);
    }

    /**
     * SSOT Update:
     * @param dt - Scaled Simulation Delta Time (0 if paused)
     * @param battleTime - Current Battle Time (for procedural shaders)
     * @param engine - Reference to game engine for reading Agent state
     */
    update(
        dt: number, 
        battleTime: number, 
        ambientType: string, 
        getTerrainHeight: (x: number, y: number) => number,
        engine?: GameEngine 
    ) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            // Apply Time Dilation to Delays
            if (p.delay && p.delay > 0) { 
                p.delay -= dt; 
                continue; 
            }

            p.life -= dt;

            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop(); count--; continue;
            }

            if (p.locked) { 
                p.rotation += p.vRotation * dt; 
                continue; 
            }

            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX, dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) p.life = 0; 
            }

            VFXPhysics.update(p, dt, getTerrainHeight);
        }

        // Decals also respect time scale
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) this.state.decals.splice(i, 1);
        }

        // Pass engine for dynamic map bounds
        this.ambience.update(dt, ambientType, this.state, engine);

        // Update Agent-based Continuous VFX (Dust, Status)
        if (engine) {
            this.agentVFX.update(dt, engine, this);
        }
    }
}

import { VFXStateManager } from "./state";
import { GameEngine } from "../../game";
import { HexUtils } from "../../utils";

export class VFXAmbience {
    private timer: number = 0;

    public update(dt: number, type: string, state: VFXStateManager, engine?: GameEngine) {
        if (type === 'NONE') return;

        this.timer += dt;

        let rate = 0.15;
        if (type === 'SNOW' || type === 'ASH') rate = 0.03;
        if (type === 'SAND') rate = 0.005; 

        if (this.timer > rate) {
            this.timer = 0;

            const p = state.getParticle();
            p.type = 'ATMOSPHERE'; 

            // Dynamic bounds based on map size if engine is available
            let boundsW = 2000;
            let boundsH = 1400;
            let offsetX = -400;
            let offsetY = -400;

            if (engine) {
                const cfg = engine.mapConfig;
                // Approximate pixel bounds based on hex grid size
                // Width ~ 1.5 * size * cols, Height ~ 1.7 * size * rows
                boundsW = cfg.w * 80 + 800; // Extra padding
                boundsH = cfg.h * 80 + 800;
                // Center roughly around map center 
                // We assume map starts at 0,0 but we want coverage beyond edges
                offsetX = -400; 
                offsetY = -400;
            }

            let x = Math.random() * boundsW + offsetX;
            const y = Math.random() * boundsH + offsetY;

            p.z = Math.random() * 400 + 50; 

            if (type === 'SNOW') {
                p.x = x; p.y = y;
                p.color = '#fff';
                p.size = Math.random() * 2.5 + 1.5;
                p.vx = 40 + Math.random() * 30; // Wind
                p.vy = 80 + Math.random() * 40; // Fall
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'ASH') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#1c1917' : '#451a03'; 
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 30 + Math.random() * 20;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#f59e0b' : '#ef4444';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 40;
                p.vy = -40 - Math.random() * 30; 
                p.life = 2.5; p.maxLife = 2.5;
                p.blendMode = 'screen'; 
            } else if (type === 'SPORES') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2.5 + 0.5;
                p.vx = (Math.random() - 0.5) * 15;
                p.vy = (Math.random() - 0.5) * 15;
                p.life = 6.0; p.maxLife = 6.0;
                p.blendMode = 'screen';
            } else if (type === 'SAND') {
                // Spawn off-screen left
                p.x = offsetX; // Start from left edge
                p.y = Math.random() * boundsH + offsetY; 

                p.color = Math.random() > 0.6 ? '#fcd34d' : '#d97706'; 
                p.size = Math.random() * 2 + 1; 

                p.vx = 1200 + Math.random() * 600; 
                p.vy = 50 + Math.random() * 30; 

                p.life = 1.8; p.maxLife = 1.8; 
                p.blendMode = 'source-over';
            }

            state.particles.push(p);
        }
    }
}

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_SCALE, VFX_PARAM } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { UnitCorePainter } from "./UnitCorePainter";
import { SpriteManager } from "../../../sprites";
import { VisualMath } from "../../../math/VisualMath";
import { FACTION_VISUALS } from "../../../../../data/vfx/faction_visuals";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        const vx = agent.physics.vx;
        const vy = agent.physics.vy;
        const speedSq = vx*vx + vy*vy;

        let tiltAngle = 0;
        let isHighSpeed = false;

        // SSOT: Use defined thresholds
        if (speedSq > VFX_PARAM.SPEED_TRAIL_THRESHOLD_SQ) {
            const speed = Math.sqrt(speedSq);
            isHighSpeed = speed > VFX_PARAM.SPEED_TILT_THRESHOLD;

            const dirX = vx / speed;
            const dot = dirX * agent.facing; 
            const maxTilt = 0.5; 
            // Calculate tilt based on reference max speed
            let tiltFactor = Math.min(1.0, speed / VFX_PARAM.SPEED_MAX_TILT_REF) * maxTilt;

            if (dot > 0) tiltAngle = tiltFactor * agent.facing;
            else tiltAngle = -tiltFactor * agent.facing * 1.5; 
        }

        const finalRotation = agent.physics.angle + tiltAngle;

        // Draw High Speed Ghosts / Trails (Behind Body)
        if (isHighSpeed && !isSilhouette && agent.hp > 0) {
            const history = agent.trailHistory;
            const step = 2;
            const maxGhosts = 2;
            const faction = FACTION_VISUALS[agent.team];

            for (let i = Math.max(0, history.length - 1 - (maxGhosts*step)); i < history.length - 1; i += step) {
                const pos = history[i];
                const opacity = (i / history.length) * 0.3; 
                ctx.save();
                const ghostY = VisualMath.getVisualBodyCenterY(pos.y, pos.z);
                ctx.translate(pos.x, ghostY);
                ctx.scale(UNIT_SCALE, UNIT_SCALE);
                ctx.rotate(finalRotation * 0.5);
                ctx.scale(agent.facing > 0 ? 1 : -1, 1);
                ctx.globalAlpha = opacity;
                ctx.globalCompositeOperation = 'screen'; 
                ctx.fillStyle = faction.flightTrailColor; 
                ctx.beginPath();
                ctx.moveTo(-10, -40); ctx.lineTo(10, -40);
                ctx.lineTo(5, 10); ctx.lineTo(-5, 10);
                ctx.fill();
                ctx.restore();
            }
        }

        ctx.save(); 
        const pz = agent.physics.z;
        const bodyY = VisualMath.getVisualBodyCenterY(py, pz);
        ctx.translate(px, bodyY); 

        let hitBrightness = 0;
        let squashX = 1.0;
        let squashY = 1.0;

        if (agent.hitFlashTimer > 0 && !isSilhouette) {
            const trauma = agent.hitFlashTimer / 0.1; 
            squashY = 1.0 - (trauma * 0.3);
            squashX = 1.0 + (trauma * 0.2);
            hitBrightness = 100 + Math.sin(t * 50) * 80;
        }

        // Spawn Animation: Drop-In instead of Stretch
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 

            // Drop from height (-40px) to 0
            const dropOffset = (1 - eased) * -40;
            ctx.translate(0, dropOffset);

            // Fade in
            ctx.globalAlpha *= eased;
        }

        ctx.scale(UNIT_SCALE * squashX, UNIT_SCALE * squashY);
        ctx.rotate(finalRotation);

        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(70%)'; 
        } else if (hitBrightness > 0) {
             ctx.filter = `brightness(${hitBrightness}%) contrast(120%)`;
        }

        // Layer 1: Rear Effects (Ribbons/Engines)
        if (agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            // Re-use threshold logic for trails
            if (agent.movementType === MovementType.FLYING || speedSq > 5000) {
                UnitFlightPainter.drawRibbonTrail(ctx, agent, t);
            }
            if (agent.movementType === MovementType.FLYING) {
                UnitFlightPainter.drawFlightVFX(ctx, agent, t);
            }
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (agent.visualStatus === 'POLYMORPH' && !isSilhouette) {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Layer 2: Main Body
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Layer 4: Overlay Status (Ice Block)
            if (agent.visualStatus === 'FROZEN' && !isSilhouette) {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};
